window.COURSE = {"version":"1.0.0","updated":"2026-09-23","title":"知产实战研习室","chapters":[{"id":"C","name":"版权","full":"版权与相关权利","scene":"内容工作室","description":"照片、代码、音乐、表演。先理清对象，再谈怎么用。","session":2,"file":"SUSS Session 2 国际和比较版权法.pptx","color":"#3568ae","symbol":"©","timeline":[["1886","伯尔尼公约","围绕作品与作者建立国际保护框架。"],["1961","罗马公约","将表演者、录音制作者和广播机构纳入相关权利框架。"],["1996","WPPT 通过","回应表演与录音在数字环境中的利用。"],["2012 / 2020","北京条约通过 / 生效","扩展与更新视听表演的国际保护。"]]},{"id":"T","name":"商标","full":"商标与地理标志","scene":"品牌事务所","description":"名称、包装、出海、加盟。判断来源识别与权利边界。","session":3,"file":"SUSS session 3 国际和比较商标法.pptx","color":"#8b58a2","symbol":"®","timeline":[["1883","巴黎公约","为商标等工业产权建立跨境保护框架。"],["1994","TRIPS 与 TLT","前者设置有关最低标准，后者着重程序协调。"],["1999","驰名商标联合建议","提供保护标准的参考；建议性质不同于生效法条。"],["2006 / 2009","新加坡条约通过 / 生效","推动商标手续、通信等程序现代化。"]]},{"id":"P","name":"专利","full":"专利及相关保护","scene":"创新实验室","description":"产品、程序、药品、芯片。把技术与保护条件对上。","session":4,"file":"SUSS Session 4 国际和比较专利法.pptx","color":"#087f7a","symbol":"⚙","timeline":[["1883","巴黎公约","形成专利独立性等国际框架。"],["1970","PCT 签订","提供国际申请途径，授权仍由有关国家或地区决定。"],["1994","TRIPS","规定专利条件、权利、例外及有关最低标准。"],["2017","第 31bis 条生效","将特定药品生产出口机制纳入协定。"]]},{"id":"S","name":"商业秘密","full":"商业秘密与经营选择","scene":"企业资料室","description":"配方、数据、员工、合作。查来源、权限与保密措施。","session":5,"file":"SUSS Session 5 国际和比较商业秘密保护.pptx","color":"#b6682f","symbol":"◇","timeline":[["1993 / 1994","中国制度与 TRIPS","中国反不正当竞争法及 TRIPS 分别建立相关保护框架。"],["2019","德国秘密保护立法","作为课件比较不同制度安排的一个节点。"],["2024","印度法律委员会报告","提出专门立法建议；报告及草案不等于已经生效。"],["2025","中国反不正当竞争法修订","本课使用修订后第 10 条讲解，另标课件旧编号。"]]}],"sources":[{"id":"tripsCT","title":"WTO：TRIPS 版权与商标条款","url":"https://www.wto.org/english/docs_e/legal_e/27-trips_04_e.htm"},{"id":"tripsGI","title":"WTO：地理标志与外观设计","url":"https://www.wto.org/english/docs_e/legal_e/27-trips_04b_e.htm"},{"id":"tripsP","title":"WTO：专利及布图设计条款","url":"https://www.wto.org/english/docs_e/legal_e/31bis_trips_04c_e.htm"},{"id":"trips31bis","title":"WTO：第 31bis 条与药品出口机制附件","url":"https://www.wto.org/english/tratop_e/trips_e/wtl641_e.htm"},{"id":"tripsS","title":"WTO：未披露信息与竞争条款","url":"https://www.wto.org/english/docs_e/legal_e/31bis_trips_04d_e.htm"},{"id":"berne","title":"WIPO：伯尔尼公约资料","url":"https://www.wipo.int/en/web/treaties/ip/berne/index"},{"id":"wppt","title":"WIPO：WPPT 说明","url":"https://www.wipo.int/en/web/treaties/ip/wppt/summary_wppt"},{"id":"beijing","title":"WIPO：北京条约说明","url":"https://www.wipo.int/en/web/treaties/ip/beijing/summary_beijing"},{"id":"pct","title":"WIPO：PCT 国家阶段","url":"https://www.wipo.int/en/web/pct-system/national-phase"},{"id":"epo","title":"EPO：软件与进一步技术效果（2026）","url":"https://www.epo.org/en/legal/guidelines-epc/2026/g_ii_3_6.html"},{"id":"prc","title":"国家知识产权局：2025 修订反不正当竞争法","url":"https://www.cnipa.gov.cn/art/2026/5/20/art_104_206437.html"},{"id":"hgb74","title":"德国 HGB 第 74 条：补偿","url":"https://www.gesetze-im-internet.de/hgb/__74.html"},{"id":"hgb74a","title":"德国 HGB 第 74a 条：合理范围与期限","url":"https://www.gesetze-im-internet.de/hgb/__74a.html"},{"id":"india","title":"印度法律委员会第 289 号报告（法院官网存档）","url":"https://delhihighcourt.nic.in/files/2025-05/reports/289_lcir_part_1.pdf"}],"sourceMap":{"C":["tripsCT","berne"],"C08":["tripsCT"],"C09":["tripsCT","wppt"],"C10":["beijing"],"T":["tripsCT"],"T09":["tripsGI"],"P":["tripsP"],"P01":["tripsGI"],"P02":["pct","tripsP"],"P05":["epo","tripsP"],"P09":["trips31bis","tripsP"],"S":["tripsS"],"S05":["hgb74","hgb74a","tripsS"],"S06":[],"S07":[],"S08":["prc","tripsS"],"S09":["india","tripsS"]},"corrections":[["条约最低标准与国内法","保护期、使用要求及例外先注明条约框架，不能当作各国统一的完整规则。"],["PCT 与药品审批","国际申请不等于全球授权；专利链接不是自动把二十年变为三十年的公式。"],["商业秘密条文时点","中国相关条文使用 2025 修订法第 10 条；日、韩及台湾地区比较明确以课件给定版本为教学范围。"],["政策观点与立法建议","地理标志评价、刑罚政策讨论和印度报告建议均不冒充已生效规范。"],["数据与手续","不将各地数据保护一律写成禁止全部申请；不将录音包装符号当成所有条约的统一保护前提。"]],"lessons":[{"id":"C01","title":"作品没有登记，还受保护吗","case":"摄影师的海外广告","pages":"3、32","scope":"伯尔尼公约自动保护、国民待遇；是否要求固定由有关国内法规定","nodes":[{"label":"自动保护","text":"伯尔尼框架下，享有和行使版权不以登记等手续为前提。","fact":"没有登记证书，不等于照片没有版权。"},{"label":"国民待遇","text":"符合公约条件的外国作品，在保护地获得公约规定的国民待遇。","fact":"进入另一市场时，仍要查当地具体保护规则。"},{"label":"固定与证据","text":"成员可对作品固定作要求；创作记录有助证明事实。","fact":"源文件能支持作者身份，但不会自动覆盖广告授权范围。"}],"evidence":[{"label":"交付清单","text":"原创照片 12 张，包含拍摄源文件；没有登记证书。"},{"label":"投放需求","text":"客户拟在另一成员市场的电商广告中使用照片，尚未确定使用期限。"}],"questions":[{"id":"C01-q1","stem":"广告公司收到原创照片，摄影师未登记。按本关伯尔尼框架，哪些判断成立？","options":[{"id":"1","text":"客户付款即取得所有未来用途的权利","why":"付款不能替代具体权属及许可约定。","correct":false},{"id":"0","text":"不能仅凭未登记认定照片不受保护","why":"自动保护不以登记为一般前提。","correct":true},{"id":"2","text":"需要核实此次广告使用的授权范围","why":"作品受保护与客户获得许可是两件事。","correct":true},{"id":"3","text":"必须先在所有投放国登记才能产生版权","why":"这把版权错误理解为普遍的注册取得制。","correct":false}]},{"id":"C01-q2","stem":"摄影师来自另一成员国，品牌在本地销售使用其作品的海报。哪些核查方向正确？","options":[{"id":"3","text":"外国作品无需考虑本地版权制度","why":"国民待遇恰恰涉及保护地制度。","correct":false},{"id":"0","text":"先确认作品符合公约适用条件","why":"不能省略作品和作者的连接条件。","correct":true},{"id":"2","text":"只适用摄影师国籍国的全部规则","why":"跨境争议不能简单只看国籍。","correct":false},{"id":"1","text":"查保护地给予的权利与救济","why":"国民待遇不等于各国规则完全相同。","correct":true}]},{"id":"C01-q3","stem":"团队只听过一次即兴口头创作，没有录音。根据本关固定规则，哪些做法妥当？","options":[{"id":"2","text":"区分固定要求与版权登记","why":"将作品记录下来和办理登记不同。","correct":true},{"id":"1","text":"确认所有成员对口头作品的规则相同","why":"成员在固定问题上存在空间。","correct":false},{"id":"3","text":"没有录音便可在全球不受限制地利用","why":"事实不足以作出全球性结论。","correct":false},{"id":"0","text":"核实有关法域是否要求该类作品固定","why":"伯尔尼允许成员对固定作规定。","correct":true}]},{"id":"C01-q4","stem":"品牌已有一份版权登记证，但合同只写“内部展示”。现拟公开投放，哪些判断有依据？","options":[{"id":"3","text":"有证书即可省略投放地区核查","why":"地区仍可能影响合同和适用法。","correct":false},{"id":"1","text":"应核对权利人和许可条款","why":"两者共同影响能否作本次使用。","correct":true},{"id":"2","text":"登记后任何购买者都可自由改编","why":"登记不产生这种普遍授权。","correct":false},{"id":"0","text":"登记证不能自动扩大合同用途","why":"权属证据不等同于公开投放许可。","correct":true}]},{"id":"C01-q5","stem":"海外客户委托原创插画，只保存了付款截图。哪些材料适合补充？","options":[{"id":"0","text":"创作记录及交付版本","why":"有助核对创作与作品范围。","correct":true},{"id":"1","text":"一份声明所有国家法律完全一致的承诺","why":"不能用承诺抹去法域差异。","correct":false},{"id":"2","text":"说明用途、地域和期限的授权文件","why":"让实际使用与授权相对应。","correct":true},{"id":"3","text":"作者或合法授权方的身份资料","why":"有助核实授权链条。","correct":true}]}],"role":"品牌项目负责人","scenario":"摄影师交付了原创照片和拍摄源文件，没有做版权登记。团队要把照片投放到另一个伯尔尼公约成员市场，客户说“没登记就能随便用”。","summary":"版权保护通常不靠登记来启动，但具体权利、固定要求和跨境适用仍要看保护地规则。","variation":{"labels":["没有登记","只拿到一张登记证书"],"results":["不能仅因未登记否认保护。下一步核实权利归属和授权。","证书不能代替对用途、期限、地区的授权核查。"]},"worked":"先辨认对象是原创照片，再区分“是否产生保护”和“是否获得使用许可”。未登记不能直接推导为可免费使用；跨境投放还需核对保护地与合同范围。"},{"id":"C02","title":"创意、代码和数据怎么分","case":"相似的点餐产品","pages":"32–33","scope":"TRIPS 第 9.2、10 条；只讨论版权保护对象","nodes":[{"label":"想法与方法","text":"想法、程序步骤、操作方法和数学概念本身不因版权被独占。","fact":"“扫码点餐”这个点子和实现它的具体代码不同。"},{"label":"代码与表达","text":"源代码与目标代码按文学作品保护；独立创作仍需核实具体复制行为。","fact":"功能相同不能直接证明复制了代码。"},{"label":"选择与编排","text":"有智力创作的资料选择或排列可以受保护，不因此垄断资料本身。","fact":"公开菜价与特别设计的菜单编排要分开分析。"}],"evidence":[{"label":"研发记录","text":"本团队保留独立编程记录，未接触竞品代码。"},{"label":"设计需求","text":"同事提议照搬竞品插画与独特菜单分类，理由是“数据都是公开的”。"}],"questions":[{"id":"C02-q1","stem":"两家公司独立开发扫码点餐，功能相同、代码不同。哪些判断符合本关？","options":[{"id":"1","text":"先想到扫码点餐就拥有全部实现方案","why":"这把想法与表达混为一谈。","correct":false},{"id":"0","text":"功能相同本身不能证明复制表达","why":"版权不独占抽象业务想法。","correct":true},{"id":"2","text":"具体源代码可能属于保护对象","why":"TRIPS 将计算机程序作为文学作品保护。","correct":true},{"id":"3","text":"只要产品属于软件便没有版权","why":"软件并不因数字形式被排除。","correct":false}]},{"id":"C02-q2","stem":"开发者获得竞品编译后的目标代码，拟直接放入产品。哪些判断正确？","options":[{"id":"0","text":"目标代码也在本关保护范围内","why":"保护不限于人能直接阅读的源代码。","correct":true},{"id":"2","text":"看不懂目标代码就不能侵犯版权","why":"可读性不是这一保护的条件。","correct":false},{"id":"1","text":"需要检查是否得到相应复制使用授权","why":"拿到文件不等于取得许可。","correct":true},{"id":"3","text":"只要更改软件名称就变成独立创作","why":"改名没有改变复制事实。","correct":false}]},{"id":"C02-q3","stem":"餐饮平台整理公开营业时间，并有独创的主题选择与排列。哪些说法成立？","options":[{"id":"3","text":"投入工时足够多就必然满足 TRIPS 创作标准","why":"劳动量不能直接替代规定的创作条件。","correct":false},{"id":"2","text":"他人是否复制编排与是否使用数据要分开","why":"这是判断对象的关键区分。","correct":true},{"id":"1","text":"公开营业时间因此全部成为平台私有","why":"编排保护不扩张到数据本身。","correct":false},{"id":"0","text":"可能保护有创作性的选择或排列","why":"需关注编排是否构成智力创作。","correct":true}]},{"id":"C02-q4","stem":"新团队使用同一数学公式，但自行画图和编程。哪些结论适当？","options":[{"id":"0","text":"公式本身不由本关版权规则独占","why":"TRIPS 区分概念与表达。","correct":true},{"id":"2","text":"仍要核实是否复制了他人的具体图文","why":"独立实现不等于任何素材均可取用。","correct":true},{"id":"3","text":"数学公式公开意味着所有教材插图也公开可用","why":"公式与插图是不同对象。","correct":false},{"id":"1","text":"必须购买最先使用公式者的版权许可","why":"不能仅因采用公式作此判断。","correct":false}]},{"id":"C02-q5","stem":"旅游应用想复用城市交通数据和竞品地图插画。哪些行动有依据？","options":[{"id":"1","text":"检查插画的授权范围","why":"原始事实公开不等于图像表达无权利。","correct":true},{"id":"2","text":"保留独立设计记录","why":"有助说明具体表达的来源。","correct":true},{"id":"0","text":"把数据、地图插画与页面编排分别核查","why":"不同对象的判断标准不同。","correct":true},{"id":"3","text":"用“网上能下载”替代全部授权检查","why":"可下载并不直接表示可商业利用。","correct":false}]}],"role":"软件产品经理","scenario":"竞品也做了扫码点餐。你的团队独立写代码，却准备直接复制竞品菜单数据库的特别分类和页面插画。","summary":"版权保护具体表达；同一个想法可以有不同表达，数据库还要分清数据与有创造性的选择编排。","variation":{"labels":["只采用扫码点餐想法","复制页面插画和代码"],"results":["不能仅凭想法相同认定版权复制；继续比较具体表达。","分析重点转为具体表达及授权，功能相同不是免责理由。"]},"worked":"先把材料拆成点子、代码、插画、原始数据和编排。独立实现功能与复制插画是不同事实；公开数据也不能直接消除编排表达的保护。"},{"id":"C03","title":"买了使用权，也能删署名吗","case":"广告片重新剪辑","pages":"4–9、32","scope":"伯尔尼第 6bis 条与 TRIPS 第 9.1 条；国内人格权细节可能不同","nodes":[{"label":"署名","text":"伯尔尼承认作者主张作者身份的权利。","fact":"转让经济权利后仍要考虑署名。"},{"label":"完整性","text":"反对有损作者名誉或声誉的歪曲、割裂等行为。","fact":"调整时长不自动等于侵害；需看具体修改与影响。"},{"label":"制度分层","text":"TRIPS 对伯尔尼的纳入不包含第 6bis 条人格权义务。","fact":"这不表示成员国内法或伯尔尼自身不保护人格权。"}],"evidence":[{"label":"合同摘录","text":"品牌取得本次广告投放所需的经济权利；署名安排未说明。"},{"label":"剪辑建议","text":"把导演的警示采访剪成推荐产品，并去掉姓名。"}],"questions":[{"id":"C03-q1","stem":"品牌说“我们买了传播权，所以作者没有署名权”。哪些判断正确？","options":[{"id":"1","text":"传播权转让当然消灭作者身份","why":"转让经济权利不能支持该结论。","correct":false},{"id":"0","text":"经济权利与人格权需要分开","why":"伯尔尼第 6bis 条明确作此区分。","correct":true},{"id":"2","text":"应核查署名处理及适用规则","why":"具体呈现与救济仍需结合相关制度。","correct":true},{"id":"3","text":"TRIPS 未纳入人格权就代表作者全球无此权","why":"这误读了不同条约的关系。","correct":false}]},{"id":"C03-q2","stem":"剪辑师把访谈剪成作者从未支持的立场，且有损声誉。按题定事实，哪些分析相关？","options":[{"id":"2","text":"任何付费作品都不再有人格权问题","why":"付款并未产生该效果。","correct":false},{"id":"3","text":"只有未经修改的作品才可能侵害人格权","why":"修改恰是这里的核查对象。","correct":false},{"id":"1","text":"把版权许可和人格权问题分别审查","why":"已有经济许可不能结束分析。","correct":true},{"id":"0","text":"检查歪曲修改与声誉损害","why":"与第 6bis 条完整性保护有关。","correct":true}]},{"id":"C03-q3","stem":"平台只调整视频编码，未改变内容或署名。哪些说法稳妥？","options":[{"id":"1","text":"任何编码调整都自动触发人格权侵害","why":"缺少有损声誉等相关事实。","correct":false},{"id":"3","text":"未损害声誉便能免除全部版权许可","why":"不能以一个问题替代全部权利分析。","correct":false},{"id":"2","text":"仍可检查许可是否涵盖技术处理","why":"许可问题与人格权判断并行。","correct":true},{"id":"0","text":"不能仅因文件发生变化就断定损害声誉","why":"第 6bis 条并非禁止一切技术变化。","correct":true}]},{"id":"C03-q4","stem":"公司法律简报称 TRIPS 没有第 6bis 条义务，所以国内人格权条款无效。哪些纠正合理？","options":[{"id":"3","text":"只需研究经济权利即可处理所有修改纠纷","why":"本案可能涉及人格权。","correct":false},{"id":"0","text":"TRIPS 的排除不废除伯尔尼本身义务","why":"两者不能混为一体。","correct":true},{"id":"1","text":"国内人格权规则仍需独立核查","why":"不能从 TRIPS 的范围推导国内法失效。","correct":true},{"id":"2","text":"该简报已正确解释所有国内法","why":"结论远超条约文本。","correct":false}]},{"id":"C03-q5","stem":"出版社将插画经济权利转售，买方拟将作者姓名换成公司名。哪些步骤适当？","options":[{"id":"3","text":"保留原作者及授权链条记录","why":"便于同时核对身份与经济授权。","correct":true},{"id":"1","text":"核查署名安排和当地规则","why":"有助判断具体行为与救济。","correct":true},{"id":"0","text":"区分作者身份与经济权利受让人","why":"公司取得权利不自动成为创作者。","correct":true},{"id":"2","text":"用受让合同直接证明公司创作了插画","why":"权利取得和创作事实不同。","correct":false}]}],"role":"广告制片人","scenario":"导演转让了广告片的一部分经济权利。品牌要求删除作者署名，并把访谈重新剪成有损其声誉的相反意思。","summary":"经济权利处理作品怎样赚钱；人格权涉及作者身份和特定有损声誉的修改，不能只凭付费推定一并消失。","variation":{"labels":["只缩短片尾空白","改成相反立场并损害声誉"],"results":["需要结合授权和实际影响判断，不能把所有修改都视为有损声誉。","进入完整性权利的核心核查范围，经济权利转让不能终止分析。"]},"worked":"先确认转让的是哪些经济权利，再分别检查署名和有损声誉的修改。不能因有剪辑权就跳过人格权，也不能因发生修改就自动认定违反第 6bis 条。"},{"id":"C04","title":"一次改编，可能动了几种权利","case":"小说变成短剧","pages":"12–13、34–35","scope":"伯尔尼经济权利与 TRIPS 第 11 条出租权框架","nodes":[{"label":"使用行为","text":"复制、翻译、改编、表演和传播属于不同分析对象。","fact":"印刷许可不能直接证明具有改编许可。"},{"label":"许可边界","text":"核对授权主体、行为、渠道、地域和期限。","fact":"短剧上线与纸书印刷的使用方式不同。"},{"label":"出租边界","text":"TRIPS 对程序及电影的商业出租设规则，并规定特定例外。","fact":"设备中的程序不是出租主要标的时，程序出租义务存在例外。"}],"evidence":[{"label":"已有许可","text":"仅许可纸质书印刷 3,000 册，没有短剧或翻译条款。"},{"label":"业务计划","text":"开发英文电子版、短剧和有声节目，并向公众收费提供。"}],"questions":[{"id":"C04-q1","stem":"出版社只获纸书复制许可，却要拍电影。哪些判断有依据？","options":[{"id":"1","text":"后续播放还需检查相应权利","why":"制作和传播是不同环节。","correct":true},{"id":"0","text":"电影化需要另查改编许可","why":"复制与改编不是同一行为。","correct":true},{"id":"3","text":"只要保留原名就无需再核查授权","why":"署名不能代替经济许可。","correct":false},{"id":"2","text":"购买纸书库存就自动取得改编权","why":"所有权不等于相关版权。","correct":false}]},{"id":"C04-q2","stem":"内容团队将中文故事译为英文并出售电子版。哪些行为需要辨认？","options":[{"id":"1","text":"电子复制及对外提供行为","why":"译文出售还涉及具体利用方式。","correct":true},{"id":"0","text":"翻译行为","why":"语言转换涉及翻译权问题。","correct":true},{"id":"3","text":"翻译后原作权利自然消失","why":"翻译没有取消原作权利。","correct":false},{"id":"2","text":"仅审查实体书出租就足够","why":"与题定使用不对应。","correct":false}]},{"id":"C04-q3","stem":"租赁公司出租设备，程序只是运行设备的附带部分，并非租赁主要对象。按 TRIPS 第 11 条，哪些说法正确？","options":[{"id":"3","text":"任何程序租赁都在这一例外之内","why":"是否为主要标的是关键事实。","correct":false},{"id":"0","text":"程序出租权义务有相应例外","why":"条文针对程序不是主要标的的出租作区分。","correct":true},{"id":"2","text":"设备带程序就绝对禁止出租","why":"忽略条文限定。","correct":false},{"id":"1","text":"不能据此推导可擅自复制软件","why":"出租例外不等于复制许可。","correct":true}]},{"id":"C04-q4","stem":"影片出租导致广泛复制并实质损害复制权。按第 11 条，哪些分析适当？","options":[{"id":"1","text":"电影永远不受出租权义务约束","why":"忽略广泛复制和实质损害条件。","correct":false},{"id":"2","text":"不能把所有成员的电影出租制度视为完全一致","why":"条约框架留有具体实施差别。","correct":true},{"id":"3","text":"只要租金很低便自动排除该规则","why":"租金高低不是这里的核心标准。","correct":false},{"id":"0","text":"需关注电影出租义务例外的限制条件","why":"题定损害与条文触发条件对应。","correct":true}]},{"id":"C04-q5","stem":"播客公司购买小说实体书，计划录制收费有声节目。哪些处理方式合理？","options":[{"id":"2","text":"核对语言、地区和期限","why":"避免授权范围与使用不匹配。","correct":true},{"id":"0","text":"列出朗读录制与向公众提供的具体行为","why":"据此核查权利范围。","correct":true},{"id":"1","text":"找到能授予相应权利的主体","why":"书店售书不一定能授予节目制作权。","correct":true},{"id":"3","text":"以购书收据代替整套内容授权","why":"收据不足以证明这些许可。","correct":false}]}],"role":"内容公司制片人","scenario":"团队获准印刷一本小说，接着想翻译成英文、改编短剧、制作有声版。租赁部门还要出租装有软件的设备。","summary":"把“准备做的行为”逐项列出来，才能看出需要核查哪些权利；一种许可通常不能说明所有用途。","variation":{"labels":["只按约印刷纸书","追加英文短剧"],"results":["可先对照印量等许可条件，不能由此推定其它用途。","新增翻译、改编及传播等核查事项，需逐一确认。"]},"worked":"从产品名称转向实际行为：英文版涉及翻译，短剧涉及改编及后续传播。每个行为都回到许可范围，不把一次签约理解为取得整条产业链权利。"},{"id":"C05","title":"老作品现在就能用了？","case":"旧电影上线排期","pages":"10–11、36、41","scope":"条约最低期限；具体题目注明采用的起算规则，不代表各国相同","nodes":[{"label":"自然人作者","text":"伯尔尼一般最低标准为作者有生之年加死后 50 年。","fact":"作者死亡时间比扫描文件日期更相关。"},{"label":"不同起算","text":"匿名作品、电影等有特别规定；TRIPS 非按自然人寿命计算的期限有适用范围。","fact":"先找适用类别，不能一律按上传日期。"},{"label":"最低与实际","text":"国内法可能更长；录音、表演、广播也不能混用期限。","fact":"电影作品与其中录音不是简单共用一个时钟。"}],"evidence":[{"label":"档案表","text":"作者卒于 1970 年；文章为已知自然人作者作品。"},{"label":"练习前提","text":"本关计算示例假设保护地适用死后 50 年、从死亡年份年末计算，无其它延长因素。"}],"questions":[{"id":"C05-q1","stem":"平台只知道一幅插画上传于 1990 年，作者身份已知但生卒不明。哪些判断正确？","options":[{"id":"3","text":"知道图片很老即可无需调查","why":"年代印象不是期限证据。","correct":false},{"id":"0","text":"上传日期不足以替代作者死亡日期","why":"本类通常需要作者寿命相关事实。","correct":true},{"id":"2","text":"所有旧图从上传满 50 年便自由使用","why":"起算点和法域均不明确。","correct":false},{"id":"1","text":"应先核查保护地和适用期限","why":"国内期限可能高于条约最低标准。","correct":true}]},{"id":"C05-q2","stem":"题设采用死后 50 年、自死亡年份年末计算；作者卒于 1970 年。哪些判断成立？","options":[{"id":"1","text":"不能将结果直接推广到更长期限的国家","why":"本题有明确制度前提。","correct":true},{"id":"0","text":"按该假设计算至 2020 年末","why":"需完整计算死亡后的 50 年。","correct":true},{"id":"2","text":"保护在 1970 年当天即结束","why":"没有加上死后期限。","correct":false},{"id":"3","text":"2021 年以后所有改编版本也当然无权利","why":"新版本可能包含独立受保护内容。","correct":false}]},{"id":"C05-q3","stem":"电影和匿名作品被归到“全部按作者死亡起算”。哪些纠正适当？","options":[{"id":"3","text":"作品类别不影响期限判断","why":"类别恰是第一步。","correct":false},{"id":"2","text":"匿名作品从来不受保护","why":"匿名与无版权并不等同。","correct":false},{"id":"0","text":"应检查类别的特别起算规定","why":"并非所有作品统一规则。","correct":true},{"id":"1","text":"匿名作者身份后来明确可能影响适用规则","why":"身份信息是相关事实。","correct":true}]},{"id":"C05-q4","stem":"平台把表演、录音和广播都写成 TRIPS 最低 50 年。哪些纠正有依据？","options":[{"id":"2","text":"广播和作者文学作品永远同一期限","why":"忽略主体和对象差异。","correct":false},{"id":"0","text":"表演者和录音制作者有至少 50 年标准","why":"需按相应固定或表演年份年末计算。","correct":true},{"id":"1","text":"广播机构的相关最低期限为 20 年","why":"不能与录音主体混用。","correct":true},{"id":"3","text":"最低标准意味着成员不能规定更长期限","why":"最低不是最高。","correct":false}]},{"id":"C05-q5","stem":"出版社利用已期满的原作，却下载了新译本和新插图。哪些检查仍有必要？","options":[{"id":"3","text":"核对题定保护地规则","why":"期满结论需要适用范围。","correct":true},{"id":"1","text":"新插图的期限及许可","why":"它是另外的作品对象。","correct":true},{"id":"0","text":"新译本的独立保护问题","why":"原作期满不直接消除译者表达的保护。","correct":true},{"id":"2","text":"只看原作年代就足够","why":"遗漏新增表达。","correct":false}]}],"role":"数字内容档案管理员","scenario":"平台收集已故作者的文章、匿名作品和旧电影。采购同事只按“看起来很老”决定是否免授权。","summary":"保护期先看对象、适用规则和起算事件，再计算；条约最低标准不能直接当作每个国家的实际期限。","variation":{"labels":["作者卒于 1970 年","只知道扫描于 1970 年"],"results":["按题定规则计算到 2020 年末，2021 年再评估期满后的使用。","扫描日期不足以计算作者死后期限，需要补充死亡时间和适用规则。"]},"worked":"先按题目选定规则，再用死亡年份年末加 50 年。这个计算只适用于题定条件，不直接推导其它国家或影片中所有素材都已期满。"},{"id":"C06","title":"写着“教学使用”就能复制吗","case":"培训公司的资料包","pages":"14、37–39","scope":"伯尔尼引用与教学利用、TRIPS 第 13 条；具体例外由适用法落实","nodes":[{"label":"具体例外","text":"找到保护地的引用、教学等规定及其条件。","fact":"“为了学习”不能直接代替法律依据。"},{"label":"三步检验","text":"特定特殊情况、不冲突正常利用、不无理损害权利人合法利益。","fact":"它是限制例外的框架，不是用户自行宣布免责的按钮。"},{"label":"事实核对","text":"目的、必要份量、来源说明与市场替代等都可能相关。","fact":"评论中短引文与整书替代销售的风险不同。"}],"evidence":[{"label":"培训方案","text":"向付费学员发整本扫描教材，预计学员不再需要购书。"},{"label":"评论页面","text":"少量引用已发表文章，紧接分析并标注作者和来源。"}],"questions":[{"id":"C06-q1","stem":"收费培训班拟整本扫描教材，学员因此不再购书。哪些分析有依据？","options":[{"id":"3","text":"存在教育目的就自动满足三步检验","why":"三个条件不能被目的一个因素替代。","correct":false},{"id":"1","text":"应考虑对作品正常利用的影响","why":"题面给出明显的市场替代事实。","correct":true},{"id":"0","text":"需要核查具体教学例外的适用条件","why":"用途名称不能替代条件分析。","correct":true},{"id":"2","text":"标注作者即可排除全部许可要求","why":"署名不是完整免责条件。","correct":false}]},{"id":"C06-q2","stem":"咨询报告短引已发表文章并作必要评论。哪些做法适当？","options":[{"id":"3","text":"文章发表后全部版权自然消失","why":"公开发表不等于放弃权利。","correct":false},{"id":"2","text":"只要引文很短，任何法域都必然合法","why":"仍需具体适用规则及事实。","correct":false},{"id":"1","text":"说明来源及应注明的作者","why":"来源说明是引用分析中的重要条件。","correct":true},{"id":"0","text":"核对引用份量是否为目的所需","why":"引用规模与正当目的相关。","correct":true}]},{"id":"C06-q3","stem":"团队将三步检验理解为“想用就说明理由”。哪些纠正正确？","options":[{"id":"1","text":"三个条件需要分别讨论","why":"满足一个不能替代其它条件。","correct":true},{"id":"2","text":"只要不赚钱就不影响正常利用","why":"非商业使用也可能替代市场。","correct":false},{"id":"3","text":"只要权利人没起诉就视为满足检验","why":"未起诉不能证明条件成立。","correct":false},{"id":"0","text":"它对限制和例外设定条件框架","why":"不是任意自创例外的授权。","correct":true}]},{"id":"C06-q4","stem":"同一教材，方案甲只展示必要片段，方案乙长期公开整书下载。哪些说法合理？","options":[{"id":"2","text":"两者有同一授课人便必然同样合法","why":"授课人身份不是充分条件。","correct":false},{"id":"1","text":"不能只因都叫教学就给相同结论","why":"教学名称掩盖了利用差异。","correct":true},{"id":"3","text":"公开下载没有读者限制所以更容易免责","why":"传播范围扩大不是当然免责理由。","correct":false},{"id":"0","text":"两者份量与传播范围不同","why":"关键事实会改变例外分析。","correct":true}]},{"id":"C06-q5","stem":"博物馆为内部研究制作资料，未来拟公开售卖。哪些步骤合适？","options":[{"id":"2","text":"保留所依赖规则及授权记录","why":"便于说明使用依据。","correct":true},{"id":"1","text":"区分内部研究复制与公开销售","why":"行为和对象范围发生变化。","correct":true},{"id":"3","text":"沿用研究标签即可覆盖未来全部商业行为","why":"忽略用途和条件变化。","correct":false},{"id":"0","text":"重新核查用途改变后的例外或许可","why":"原先用途分析未必涵盖销售。","correct":true}]}],"role":"企业培训负责人","scenario":"收费课程准备把一本教材完整扫描给学员，同时引用几段已发表文章作评论。团队以为写上来源就都可以。","summary":"教学目的和署名是相关事实，不是万能许可；先找具体例外，再核查条件、使用份量与正常市场。","variation":{"labels":["少量引用作评论","整书扫描替代购书"],"results":["继续核查引用例外的具体条件；份量、目的与来源提供判断线索。","正常利用和市场替代成为突出问题，教学标签不能结束分析。"]},"worked":"先把两种使用拆开。短引文是否满足条件要具体核查；整书分发明显涉及替代原作市场的问题。不能只凭署名或非营利字样得出许可结论。"},{"id":"C07","title":"教材短缺，可以自行强制许可吗","case":"外文教材的本地版本","pages":"14–15、27","scope":"伯尔尼附件的特定制度；日内瓦录音公约第 6 条条件","nodes":[{"label":"适用制度","text":"伯尔尼附件为符合条件的发展中国家提供特定翻译和复制安排。","fact":"不能把附件作为所有出版社都可直接使用的许可。"},{"label":"申请与限制","text":"具体许可有用途、期限、程序和报酬等要求。","fact":"须核实已否履行许可申请与法定步骤。"},{"label":"录音条件","text":"日内瓦公约相关强制许可限定教学或科研、境内复制且不得出口，并有公平报酬。","fact":"教学录音出口计划不能只凭教学目的获支持。"}],"evidence":[{"label":"工作邮件","text":"两周未收到作者回复；尚未向主管机关提出许可申请。"},{"label":"发行方案","text":"拟在本地教学使用，并把录音复制品卖往海外。"}],"questions":[{"id":"C07-q1","stem":"出版社联系不到作者，准备称自己的印刷为“强制许可”。哪些判断正确？","options":[{"id":"0","text":"联系困难本身不等于已经获许可","why":"仍需适用制度和程序。","correct":true},{"id":"1","text":"需核实有权机关及相关条件","why":"不能由出版商自行授予。","correct":true},{"id":"3","text":"只要定价低就不需报酬或程序","why":"低价不能替代法定要求。","correct":false},{"id":"2","text":"出版社内部盖章即可满足条约程序","why":"内部批准并非许可依据。","correct":false}]},{"id":"C07-q2","stem":"团队援引伯尔尼附件申请教材翻译许可。哪些问题应先检查？","options":[{"id":"0","text":"有关国家是否可适用该附件安排","why":"制度不是对所有主体无条件开放。","correct":true},{"id":"3","text":"附件等同永久免费复制所有作品","why":"忽略对象和限制。","correct":false},{"id":"1","text":"具体用途、等待期间与申请程序","why":"属于核查许可条件的方向。","correct":true},{"id":"2","text":"只需证明教材是外文即可","why":"语言不是全部条件。","correct":false}]},{"id":"C07-q3","stem":"按日内瓦公约第 6 条，拟通过强制许可复制录音供教学。哪些条件相关？","options":[{"id":"1","text":"许可限于授予国境内复制且不得出口","why":"地域与出口限制需要同时注意。","correct":true},{"id":"0","text":"仅用于教学或科学研究","why":"用途有限定。","correct":true},{"id":"3","text":"复制品可自由出口以补贴教育","why":"与条文出口限制冲突。","correct":false},{"id":"2","text":"依法确定公平报酬","why":"教学用途并不取消该条件。","correct":true}]},{"id":"C07-q4","stem":"大学研究录音已有题定境内强制许可，企业拟拿去做广告。哪些判断成立？","options":[{"id":"0","text":"研究用途许可不能直接覆盖广告","why":"使用目的发生改变。","correct":true},{"id":"3","text":"广告收入用于学校就不算用途变化","why":"收入去向不能改变广告行为。","correct":false},{"id":"1","text":"应另查广告利用的授权依据","why":"不能借用原制度标签。","correct":true},{"id":"2","text":"有任何强制许可就等同全面买断","why":"许可范围仍受限制。","correct":false}]},{"id":"C07-q5","stem":"跨境教育企业同时使用书籍译本和录音，哪些做法妥当？","options":[{"id":"3","text":"确认真正获准范围后安排发行","why":"发行应与许可范围一致。","correct":true},{"id":"1","text":"为出口、份数和报酬建立核查记录","why":"避免只审查教学目的。","correct":true},{"id":"2","text":"用一本书的翻译许可覆盖所有录音","why":"不同权利对象不能直接互换。","correct":false},{"id":"0","text":"分别核对作品与录音适用制度","why":"不同对象可能涉及不同条件。","correct":true}]}],"role":"教育出版社负责人","scenario":"出版社找不到教材翻译授权方，便计划自己印发本地语言教材，并把教学录音复制品出口销售。","summary":"强制许可需要适用制度、主管程序和条件；“联系不到作者”或“教育有益”本身不产生许可。","variation":{"labels":["已核实适用制度和法定许可条件","只有出版社内部批准"],"results":["可以继续办理规定程序，是否获准仍要看具体条件。","内部决议不能代替有权机关和法定许可程序。"]},"worked":"先查哪套制度适用，再查机关、程序和限制。对录音复制，境内教学、不得出口和公平报酬需同时考虑，不能只抓住其中一个条件。"},{"id":"C08","title":"一场演唱会，谁有哪份权利","case":"直播间的授权清单","pages":"16–24、40–41","scope":"罗马公约与 TRIPS 第 14 条；条约连接点、保留及国内实施需核对","nodes":[{"label":"作者与表演者","text":"歌曲作品与歌手表演是不同保护对象。","fact":"词曲许可不直接证明取得表演录制同意。"},{"label":"录音制作者","text":"录音复制涉及录音制作者权利。","fact":"购买唱片不等于可复制到商业节目。"},{"label":"广播与连接点","text":"广播有自身保护；罗马保护还要核查表演地、主体及其它连接条件和保留。","fact":"使用电视台信号与自己拍摄现场不同。"}],"evidence":[{"label":"已获授权","text":"词曲授权清单完整，但未列出歌手和录音制作者。"},{"label":"传播路径","text":"现场录制、剪辑成片，再引用电视台的转播信号。"}],"questions":[{"id":"C08-q1","stem":"平台只有词曲许可，计划录制歌手现场演唱。哪些判断正确？","options":[{"id":"3","text":"取得一个主体许可就必然覆盖整场演出","why":"忽略不同权利层次。","correct":false},{"id":"1","text":"需检查表演录制的同意与适用规则","why":"词曲许可不直接替代。","correct":true},{"id":"0","text":"歌曲作品与表演应分开核查","why":"同一演出包含不同对象。","correct":true},{"id":"2","text":"歌手演唱别人的歌便没有相关权利","why":"表演保护不要求表演者创作歌曲。","correct":false}]},{"id":"C08-q2","stem":"剪辑师购买正版唱片后，拟复制录音到广告。哪些说法成立？","options":[{"id":"0","text":"购买复制品与获得再复制许可不同","why":"实物取得不能证明该授权。","correct":true},{"id":"3","text":"唱片有价格标签就意味着商业再利用自由","why":"零售不等同全用途许可。","correct":false},{"id":"1","text":"录音制作者权利需要核查","why":"TRIPS 第 14 条涉及直接或间接复制。","correct":true},{"id":"2","text":"词曲进入公有领域就代表该新录音也无权利","why":"作品与新录音需分开。","correct":false}]},{"id":"C08-q3","stem":"电视平台收到转播请求，运营人员只审查歌词版权。哪些遗漏应补足？","options":[{"id":"0","text":"广播机构对转播等行为的相关保护","why":"信号利用是单独分析方向。","correct":true},{"id":"3","text":"只要电视信号免费接收便可任意商业转播","why":"免费接收不能推导再利用许可。","correct":false},{"id":"1","text":"节目中表演和录音的利用范围","why":"内容授权也可能需要核对。","correct":true},{"id":"2","text":"所有广播权都只能属于词曲作者","why":"主体关系错误。","correct":false}]},{"id":"C08-q4","stem":"企业希望依罗马公约主张境外表演保护。哪些资料有用？","options":[{"id":"1","text":"表演是否纳入受保护录音或广播","why":"可能构成另外的连接点。","correct":true},{"id":"0","text":"表演发生地点及成员身份","why":"是表演保护的连接点之一。","correct":true},{"id":"2","text":"只需提供演员年龄","why":"不是本关连接条件。","correct":false},{"id":"3","text":"无需考虑有关成员声明或保留","why":"公约允许特定保留，不能忽略。","correct":false}]},{"id":"C08-q5","stem":"音乐公司把罗马公约的一般手续条件套到所有条约。哪些纠正正确？","options":[{"id":"1","text":"区分录音主体与作品作者","why":"不能把不同对象的手续混用。","correct":true},{"id":"2","text":"所有音频必须登记才能享有任何权利","why":"不符合条约分层。","correct":false},{"id":"3","text":"核实具体条约与保护地适用","why":"不能只看包装有没有某符号。","correct":true},{"id":"0","text":"分别核对罗马公约与 WPPT 的规则","why":"后者规定权利不受手续条件限制。","correct":true}]}],"role":"演出平台运营人","scenario":"平台已取得词曲使用授权，计划录制歌手现场表演、复制唱片伴奏并转播电视台画面。","summary":"同一段声音或画面可能叠加作者、表演者、录音制作者和广播机构的不同利益，授权要沿利用链核查。","variation":{"labels":["自己录制歌手现场","直接转播电视台信号"],"results":["重点核查表演录制同意与作品利用，不凭词曲许可一概放行。","除了节目内容，还需核查广播机构相关权利。"]},"worked":"画出作者—表演者—录音方—广播方—平台。每增加一个利用行为，就核对相关主体；多层保护并不意味着所有情形都必然要向所有人重复购买同一种许可。"},{"id":"C09","title":"数字音乐的授权信息能删吗","case":"音乐平台迁移曲库","pages":"25–28、40–41","scope":"日内瓦录音公约、WPPT、TRIPS；技术措施及权利信息需结合具体规则","nodes":[{"label":"录音保护","text":"录音公约针对未经同意复制、特定进口与公众分发。","fact":"平台导出音源不能只看歌曲名称。"},{"label":"技术与信息","text":"WPPT 要求对符合规定的规避技术措施、移除或变更权利信息提供法律保护。","fact":"应辨认所绕过的控制与所删除字段的作用。"},{"label":"期限与手续","text":"WPPT 最低保护期至少 50 年，享有和行使权利不得以手续为条件。","fact":"不能只因缺少包装符号否认 WPPT 权利。"}],"evidence":[{"label":"迁移清单","text":"拟删除录音制作者、许可地区和授权到期日字段。"},{"label":"工程方案","text":"未确认许可便绕过音源访问限制，导出后继续向用户提供。"}],"questions":[{"id":"C09-q1","stem":"音乐平台取得歌曲作品许可后，拟复制某商业录音。哪些核查仍需要？","options":[{"id":"3","text":"只要音质降低便无需许可","why":"音质不是这里的授权依据。","correct":false},{"id":"0","text":"录音制作者的相关权利","why":"作品许可与特定录音许可不同。","correct":true},{"id":"2","text":"作品许可自动覆盖任何录音版本","why":"把对象层次混同。","correct":false},{"id":"1","text":"平台复制与分发是否在授权范围内","why":"按实际利用方式判断。","correct":true}]},{"id":"C09-q2","stem":"迁移工程准备删除权利人及许可信息。哪些说法适当？","options":[{"id":"1","text":"WPPT 对移除或变更相关信息要求法律救济","why":"不能将此看成纯排版问题。","correct":true},{"id":"2","text":"只要保留曲名就没有任何信息义务问题","why":"曲名不等于完整权利管理信息。","correct":false},{"id":"0","text":"先识别是否属于受规则保护的权利管理信息","why":"字段功能和法律条件需要核实。","correct":true},{"id":"3","text":"任何数据库字段删除都自动违法","why":"仍需符合具体规则条件。","correct":false}]},{"id":"C09-q3","stem":"工程师拟规避控制导出曲库，尚无相应许可。哪些行动合理？","options":[{"id":"2","text":"有能力绕开控制便意味着授权开放","why":"能力与许可无关。","correct":false},{"id":"0","text":"核实技术措施所保护的权利与适用规定","why":"WPPT 有针对技术措施的保护框架。","correct":true},{"id":"3","text":"数字复制不产生实体唱片所以不涉及权利","why":"数字形式没有消除复制问题。","correct":false},{"id":"1","text":"查明是否获准导出和后续使用","why":"技术可行不等于有权实施。","correct":true}]},{"id":"C09-q4","stem":"权利审核以缺少 ℗ 符号为由，否认一切 WPPT 保护。哪些纠正成立？","options":[{"id":"1","text":"应区分不同条约的手续安排","why":"录音公约之间并非完全相同。","correct":true},{"id":"2","text":"所有条约一律要求同一符号","why":"与条约差异不符。","correct":false},{"id":"3","text":"无符号可以替代授权调查","why":"不能据此放弃调查。","correct":false},{"id":"0","text":"WPPT 权利享有和行使不以手续为条件","why":"不能把符号视为统一前置要求。","correct":true}]},{"id":"C09-q5","stem":"平台比较 TRIPS 与 WPPT 的录音保护，哪些说法有依据？","options":[{"id":"0","text":"两者均有录音相关保护安排","why":"需核对具体对象和权利。","correct":true},{"id":"1","text":"WPPT 明确包含数字环境下的相关机制","why":"本关技术措施和权利信息即为例子。","correct":true},{"id":"3","text":"实施时仍需看具体成员规则和适用范围","why":"条约介绍不能替代全部国内法。","correct":true},{"id":"2","text":"WPPT 把最低期限统一降为 20 年","why":"其最低标准至少 50 年。","correct":false}]}],"role":"音乐平台产品经理","scenario":"曲库迁移时，工程师想删掉录音权利人字段，并绕过访问控制导出音源。同事称只要保留歌曲名称即可。","summary":"数字分发不仅涉及复制，还涉及技术措施、权利管理信息及不同条约的保护条件。","variation":{"labels":["完整迁移授权与权利信息","删除字段并绕开控制"],"results":["可以据此检查地区、期限与平台用途，仍需核实实际许可。","将失去授权判断依据，并增加技术措施与权利信息问题。"]},"worked":"先核对录音本身的使用权限，再识别技术措施和权利管理字段。即便复制已有许可，信息处理和规避措施也可能需要单独分析。"},{"id":"C10","title":"演员签了拍摄合同，平台能怎么用","case":"广告演员的点播版本","pages":"29–31","scope":"北京条约：视听表演、人格权及第 11 条制度选择","nodes":[{"label":"已固定表演","text":"北京条约对视听固定中的表演规定复制、发行、出租和提供给公众等权利。","fact":"电影点播属于需核查的数字用途。"},{"label":"现场与人格权","text":"未固定表演涉及广播、向公众传播和固定；人格权有署名与声誉相关保护及限定。","fact":"同意拍摄不等于任意歪曲都无问题。"},{"label":"授权或报酬","text":"第 11 条对固定表演广播及向公众传播允许一定制度选择和保留。","fact":"不能把条约选择直接当作某地已采用的规则。"}],"evidence":[{"label":"合同摘要","text":"演员同意本次拍摄，后续数字平台利用条款待核对。"},{"label":"运营方案","text":"成片点播、出租及对电视台提供广播版本。"}],"questions":[{"id":"C10-q1","stem":"平台要复制并提供演员广告成片点播。哪些权利方向相关？","options":[{"id":"1","text":"提供给公众的权利","why":"按需点播属于需核查的数字用途。","correct":true},{"id":"2","text":"只核查现场入场券销售即可","why":"与题定成片利用不对应。","correct":false},{"id":"3","text":"视听表演完全不在北京条约范围内","why":"条约正是围绕这一对象。","correct":false},{"id":"0","text":"已固定表演的复制","why":"复制成片是具体利用行为。","correct":true}]},{"id":"C10-q2","stem":"团队准备直播演员尚未录制的表演。哪些分析适当？","options":[{"id":"3","text":"只有成片出租权需要考虑","why":"未覆盖题定行为。","correct":false},{"id":"1","text":"若同时录制，另看固定行为","why":"直播与固定并非同一操作。","correct":true},{"id":"0","text":"区分广播与向公众传播","why":"条约对未固定表演规定相应权利及限定。","correct":true},{"id":"2","text":"未录制就没有任何表演者权利问题","why":"条约也处理未固定表演。","correct":false}]},{"id":"C10-q3","stem":"广告把演员的表演剪成有损其声誉的内容。哪些判断正确？","options":[{"id":"1","text":"结合视听固定的性质和具体影响","why":"条约保护存在具体限定。","correct":true},{"id":"0","text":"应考虑表演者人格权","why":"不能只查经济利用许可。","correct":true},{"id":"2","text":"收过片酬就绝对不能提出任何异议","why":"付款不支持这种普遍结论。","correct":false},{"id":"3","text":"任何剪辑无论内容都必然侵害人格权","why":"需要具体分析，不是绝对禁改。","correct":false}]},{"id":"C10-q4","stem":"广播机构称北京条约第 11 条意味着各国都只需付钱、不用授权。哪些纠正合理？","options":[{"id":"3","text":"点播、出租和广播在所有情况下完全相同","why":"利用行为应分别辨认。","correct":false},{"id":"2","text":"条约选择会自动取消所有复制权","why":"第 11 条不能如此扩张。","correct":false},{"id":"1","text":"需关注保留及适用范围","why":"不能省略有关限定。","correct":true},{"id":"0","text":"须核实有关成员是否作出制度选择","why":"条约允许不等于当地已采用。","correct":true}]},{"id":"C10-q5","stem":"演员的同一表演被做成纯声音录音与电影。哪些步骤有依据？","options":[{"id":"0","text":"区分录音和视听固定对应框架","why":"WPPT 与北京条约的对象侧重不同。","correct":true},{"id":"3","text":"一个版本获准就自动覆盖全部版本与地区","why":"超出了已有许可可证明的范围。","correct":false},{"id":"2","text":"分别保留表演者和其他权利人的资料","why":"便于处理叠加权利。","correct":true},{"id":"1","text":"核对各版本的利用方式与授权链","why":"同一次表演不等于每种用途都已授权。","correct":true}]}],"role":"影视授权协调人","scenario":"演员同意拍摄广告，品牌现在要复制成片、出租拷贝、提供点播，并将表演剪成有损演员声誉的版本。","summary":"先分清现场表演与已固定视听表演，再核对复制、发行、出租、点播等用途，以及人格权和当地制度选择。","variation":{"labels":["提供成片点播","直播尚未固定的表演"],"results":["核查已固定表演的提供给公众权及合同范围。","转向未固定表演的广播、传播和固定等分析。"]},"worked":"先以固定状态分组，再按利用行为核对权利。第 11 条关于广播和向公众传播的制度选择，不应随意覆盖所有复制或点播行为。"},{"id":"T01","title":"公司名、商标、域名各管什么","case":"新茶饮品牌准备开店","pages":"2–5","scope":"商业名称、商标与域名的功能区分；权利范围需看有关法域","nodes":[{"label":"经营主体","text":"公司名称与商号用于识别经营者。","fact":"登记公司不等于完成杯身品牌的商标核查。"},{"label":"来源标志","text":"商标帮助消费者识别商品或服务来源。","fact":"杯身名称、门店标志和包装使用应按商标问题检查。"},{"label":"网络地址","text":"域名属于网络标识安排，也可能与他人名称或商标冲突。","fact":"先注册域名不一定消除他人在先权利。"}],"evidence":[{"label":"注册清单","text":"有公司登记资料和域名付款记录，没有商标申请或检索资料。"},{"label":"开店物料","text":"门店、外卖平台和纸杯使用同一品牌名称。"}],"questions":[{"id":"T01-q1","stem":"公司完成登记和域名注册，准备上线饮料品牌。哪些步骤仍合理？","options":[{"id":"3","text":"把公司登记结果当商标授权证明","why":"两类登记功能不同。","correct":false},{"id":"2","text":"凭域名付款时间排除所有在先商标","why":"域名时间不是唯一权利依据。","correct":false},{"id":"0","text":"检索目标市场的相关商标","why":"前两项登记没有替代商标审查。","correct":true},{"id":"1","text":"核对商品及服务范围","why":"冲突判断与具体经营范围有关。","correct":true}]},{"id":"T01-q2","stem":"同一名称出现在发票、杯身和网址上。哪些分析有依据？","options":[{"id":"1","text":"杯身标志可能发挥来源识别作用","why":"它可能构成商标使用问题。","correct":true},{"id":"2","text":"同样文字在所有位置只受一种制度处理","why":"使用情境影响分析。","correct":false},{"id":"0","text":"发票上的名称可能识别经营主体","why":"要结合具体使用方式。","correct":true},{"id":"3","text":"网址必然证明网站经营者拥有同名商标","why":"网址本身不能证明该权利。","correct":false}]},{"id":"T01-q3","stem":"加盟商提出“总部把域名给我，就等于把商标也转让”。哪些纠正适当？","options":[{"id":"2","text":"同一名字的资产不能分开交易","why":"可以区分权利与合同标的。","correct":false},{"id":"3","text":"域名移交后无需再看品牌许可","why":"仍需明确商标使用依据。","correct":false},{"id":"1","text":"查看商标转让约定及程序","why":"域名转移记录不能替代。","correct":true},{"id":"0","text":"检查两种资产的转移范围","why":"域名与商标不是一项资产。","correct":true}]},{"id":"T01-q4","stem":"某商号没有作为商标注册。按巴黎公约商号保护框架，哪些判断正确？","options":[{"id":"1","text":"仍需核查具体保护地和冲突事实","why":"不是取得全球绝对排他权。","correct":true},{"id":"2","text":"未注册商标便完全没有商号保护问题","why":"遗漏商号的独立保护。","correct":false},{"id":"3","text":"商号受保护便自动拥有所有商品商标","why":"保护功能和范围不同。","correct":false},{"id":"0","text":"商号保护不当然以商标登记为前提","why":"商号与商标制度不能混同。","correct":true}]},{"id":"T01-q5","stem":"电商品牌准备出海，哪些资料应分别建立？","options":[{"id":"0","text":"主体名称及登记资料","why":"用于核对谁在经营。","correct":true},{"id":"3","text":"只保存平台店铺截图即可替代全部资料","why":"店铺截图证明范围有限。","correct":false},{"id":"2","text":"域名持有人和访问管理资料","why":"网络地址管理是独立事项。","correct":true},{"id":"1","text":"品牌使用、商标权属及许可资料","why":"用于识别品牌利用依据。","correct":true}]}],"role":"创业公司负责人","scenario":"你注册了“晴岛餐饮公司”和一个同名域名，准备把“晴岛”印在饮料杯上。团队尚未做商标检索。","summary":"公司名识别经营主体，商标识别商品或服务来源，域名帮助找到网络地址；拿到一种不表示其它权利都已取得。","variation":{"labels":["只取得域名","补做目标商品与地区检索"],"results":["只能证明网络地址取得情况，不能据此完成品牌权利审查。","开始获得与商标冲突相关的资料，仍需结合具体使用判断。"]},"worked":"先分别列出经营主体、杯身品牌和网络地址。每项记录只能证明相应事项，开店前需要针对商品、服务和市场补足权利核查。"},{"id":"T02","title":"这个标志能让人认出品牌吗","case":"茶叶包装的命名会议","pages":"9、13、15–17","scope":"TRIPS 第 15 条：显著性、使用取得及程序底线","nodes":[{"label":"区分来源","text":"文字、图形、数字、颜色组合等可成为候选标志。","fact":"先问消费者是否借它辨认来源。"},{"label":"取得显著性","text":"缺乏固有显著性时，成员可考虑使用取得的显著性。","fact":"销量、宣传和识别证据应连接到具体标志。"},{"label":"申请与审查","text":"实际使用不是提交申请的条件；成员仍可按规则审查其它理由。","fact":"能提交申请不等于保证获准。"}],"evidence":[{"label":"包装备选","text":"描述茶叶品质的文字、原创图形以及稳定使用的颜色组合。"},{"label":"市场资料","text":"有广告费用，但尚无材料说明公众如何识别该标志。"}],"questions":[{"id":"T02-q1","stem":"茶商想单凭“优质绿茶”四字识别来源。哪些分析适当？","options":[{"id":"0","text":"核查该词对相关商品的描述性","why":"描述商品不等于区分经营来源。","correct":true},{"id":"3","text":"所有普通文字一概不得成为商标","why":"要看具体组合和识别作用。","correct":false},{"id":"2","text":"字印得足够大就必然具备显著性","why":"版面尺寸不是充分条件。","correct":false},{"id":"1","text":"若主张使用取得显著性，应提供相应证据","why":"不能只主张使用年限。","correct":true}]},{"id":"T02-q2","stem":"设计团队提交文字、数字及颜色组合。按 TRIPS，哪些说法成立？","options":[{"id":"3","text":"只要是原创图形就保证没有其它驳回理由","why":"显著性外仍有审查事项。","correct":false},{"id":"2","text":"颜色组合被条约全部排除","why":"与条文不符。","correct":false},{"id":"1","text":"仍需具备区分来源的能力","why":"形式可接受不等于条件已满足。","correct":true},{"id":"0","text":"这些形式可以成为商标候选","why":"形式清单包含相关标志。","correct":true}]},{"id":"T02-q3","stem":"初创企业还没销售产品，就申请商标。哪些判断正确？","options":[{"id":"2","text":"所有申请必须附已营业三年证明","why":"误读了第 15 条。","correct":false},{"id":"3","text":"未使用表示他人可以忽略任何申请或在先权利","why":"不能作此扩张推论。","correct":false},{"id":"0","text":"实际使用不得作为提交申请的条件","why":"注意申请与最终注册的区分。","correct":true},{"id":"1","text":"仍应研究有关成员的注册要求","why":"条约不保证申请必获准。","correct":true}]},{"id":"T02-q4","stem":"营销部门认为广告预算高就证明标志已获显著性。哪些补充核查合理？","options":[{"id":"1","text":"广告如何使用该标志及覆盖相关公众","why":"把投入连接到识别事实。","correct":true},{"id":"0","text":"公众是否把标志与特定来源联系","why":"直接对应显著性功能。","correct":true},{"id":"3","text":"完全不必关心商品或服务类别","why":"显著性应结合对象分析。","correct":false},{"id":"2","text":"只看广告代理公司规模","why":"与该标志识别能力联系很弱。","correct":false}]},{"id":"T02-q5","stem":"团队想注册声音标志，并援引 TRIPS。哪些说法审慎？","options":[{"id":"2","text":"老师认为限制不好就代表条文已删除","why":"评价不等于法律变更。","correct":false},{"id":"1","text":"注意 TRIPS 文本允许成员要求视觉可感知","why":"课件对该规定的批评不改变文本存在。","correct":true},{"id":"0","text":"核查当地是否接受该类非传统标志","why":"不能仅凭国际框架推定具体接受情况。","correct":true},{"id":"3","text":"程序协调条约确保每种声音在所有国家获准","why":"程序协调不保证实体审查结果。","correct":false}]}],"role":"品牌设计负责人","scenario":"团队在“优质绿茶”、原创图形和特别颜色组合之间选择包装标志。一种标志已连续使用多年，但缺乏消费者识别资料。","summary":"标志的核心作用是区分来源；好看或经常出现，不自动等于具备商标显著性。","variation":{"labels":["只说“投了很多广告”","有持续使用及消费者识别证据"],"results":["广告投入是线索，仍需把使用与来源识别能力联系起来。","可支持使用取得显著性的分析，但仍需具体审查。"]},"worked":"把“品牌喜欢什么”转成“公众凭什么认出来源”。描述品质的文字与独创标志各有问题；广告花费不能直接替代实际识别能力。"},{"id":"T03","title":"一次申请，就有全球商标吗","case":"品牌进入两个新市场","pages":"6、13、44–45","scope":"巴黎公约的独立性；TLT 与新加坡条约的程序协调","nodes":[{"label":"独立性","text":"不同国家注册的商标通常独立分析。","fact":"甲国批准不直接证明乙国无冲突。"},{"label":"程序协调","text":"TLT 关注申请、变更、续展等手续协调。","fact":"材料格式更协调，仍需实体审查。"},{"label":"现代化程序","text":"新加坡条约涉及通信、期限救济、许可记录等程序。","fact":"程序便利不能代替当地可注册性检查。"}],"evidence":[{"label":"甲国证书","text":"已注册饮料类商标，许可经销商在甲国销售。"},{"label":"出海计划","text":"乙、丙市场尚未检索；预算只列翻译证书费用。"}],"questions":[{"id":"T03-q1","stem":"品牌持甲国商标证进入乙国。哪些行动有依据？","options":[{"id":"1","text":"了解乙国申请与审查要求","why":"具体保护要看目标市场。","correct":true},{"id":"3","text":"甲国核准可替代乙国实体审查","why":"注册独立性仍需考虑。","correct":false},{"id":"0","text":"核查乙国在先权利","why":"甲国证书不能排除当地冲突。","correct":true},{"id":"2","text":"仅翻译甲国证书即可获得全部乙国权利","why":"没有这种自动推论。","correct":false}]},{"id":"T03-q2","stem":"业务主管称 TLT 统一了各国所有注册标准。哪些纠正成立？","options":[{"id":"0","text":"TLT 重点协调行政程序","why":"不能把程序协调等同全面实体统一。","correct":true},{"id":"1","text":"仍应审查具体标志和商品范围","why":"便捷申请不保证注册。","correct":true},{"id":"3","text":"相同表格必然得到相同审查结论","why":"结论还依赖法律和事实。","correct":false},{"id":"2","text":"程序简化意味着无需任何材料","why":"简化不等于取消程序。","correct":false}]},{"id":"T03-q3","stem":"公司错过某地办理期限，计划引用新加坡条约。哪些步骤合理？","options":[{"id":"0","text":"核实当地适用的期限救济安排","why":"条约框架需结合实施。","correct":true},{"id":"1","text":"确认是否属于可救济事项及满足条件","why":"不能笼统认为都有无限延期。","correct":true},{"id":"2","text":"引用条约名称即可自动恢复任何权利","why":"需要具体条件和程序。","correct":false},{"id":"3","text":"电子递交后实体审查不再存在","why":"通信方式没有改变这一点。","correct":false}]},{"id":"T03-q4","stem":"同一商标在甲国撤销，乙国仍有注册。哪些说法正确？","options":[{"id":"3","text":"乙国有证就永远不会再被挑战","why":"当地仍可能有撤销等程序。","correct":false},{"id":"0","text":"分别核对两地权利状态","why":"不能不加分析地连带撤销。","correct":true},{"id":"2","text":"甲国任何变化必然同步取消全球注册","why":"与独立分析不符。","correct":false},{"id":"1","text":"乙国争议需看有关制度和事实","why":"注册独立性不排除当地自己的审查。","correct":true}]},{"id":"T03-q5","stem":"跨境店铺为三个市场编制预算。哪些成本不应遗漏？","options":[{"id":"1","text":"检索与冲突处理成本","why":"实体风险仍存在。","correct":true},{"id":"0","text":"各地申请、代理或程序费用","why":"不能只预算证书翻译。","correct":true},{"id":"3","text":"只需一次投入，以后全球无需管理","why":"不符合地域与维护特点。","correct":false},{"id":"2","text":"后续续展和使用管理","why":"取得权利后仍需维护。","correct":true}]}],"role":"品牌出海经理","scenario":"品牌已在甲国注册，销售团队把乙国与丙国列入上线计划，并认为国际条约会让原证书自动全球生效。","summary":"国际程序帮助处理申请，具体保护仍按有关市场审查；简化手续不等于统一所有国家的实体结论。","variation":{"labels":["只有甲国证书","已取得乙国核准"],"results":["先确认目标市场是否已有权利以及需要走何种程序。","可据此评估乙国具体范围，仍不能推定丙国结论。"]},"worked":"把目标市场分开列成申请表。每列记录检索、程序、审查和权利范围；国际协调改变手续成本，不直接抹去各列的独立性。"},{"id":"T04","title":"名字相近，就一定混淆吗","case":"电商店铺的相似包装","pages":"14、18","scope":"TRIPS 第 16 条；巴黎公约第 10bis 条不正当竞争","nodes":[{"label":"交易中使用","text":"考察未经同意的商业使用及相关在先权利。","fact":"教学讨论提及名称与包装上的来源标志不同。"},{"label":"标志与商品","text":"相同或近似标志、相同或类似商品服务是基本分析要素。","fact":"不能只比较两个字的拼写。"},{"label":"混淆与竞争","text":"相同标志用于相同商品时推定混淆；虚假陈述等还可涉及不正当竞争。","fact":"混淆推定不等于每个相似词都必然侵权。"}],"evidence":[{"label":"商品对照","text":"两家均销售茶饮，包装布局、名称和主色近似。"},{"label":"客服记录","text":"出现顾客询问“两家是否同一加盟体系”的记录。"}],"questions":[{"id":"T04-q1","stem":"茶饮店用近似标志销售类似产品，已有顾客误认加盟关系。哪些事实相关？","options":[{"id":"3","text":"只需数名称有几个相同字","why":"不能替代整体分析。","correct":false},{"id":"2","text":"只要商品售价不同便排除混淆","why":"价格不同不是必然排除条件。","correct":false},{"id":"1","text":"顾客对经营联系的误认","why":"可支持混淆可能分析。","correct":true},{"id":"0","text":"标志与商品服务的相似程度","why":"与第 16 条基本框架相关。","correct":true}]},{"id":"T04-q2","stem":"未经同意，同一标志用于与注册相同的商品。按 TRIPS，哪些判断成立？","options":[{"id":"1","text":"仍需辨认注册及相关使用事实","why":"推定不消除全部前提核查。","correct":true},{"id":"3","text":"该推定适用于任何不同商品和相似程度","why":"推定条件不能无限扩大。","correct":false},{"id":"0","text":"存在混淆可能的推定","why":"这是条文特别规定。","correct":true},{"id":"2","text":"必须证明已有一千名消费者受骗","why":"条文没有这种数量门槛。","correct":false}]},{"id":"T04-q3","stem":"竞品广告捏造“对手因质量问题倒闭”，尚无真实依据。哪些分析适当？","options":[{"id":"2","text":"只有复制商标才可能构成不正当竞争","why":"保护范围不限于复制标志。","correct":false},{"id":"0","text":"考虑虚假陈述损害竞争者的方向","why":"巴黎公约不正当竞争框架相关。","correct":true},{"id":"1","text":"与商标混淆分别分析","why":"不是所有竞争问题都归入同一要件。","correct":true},{"id":"3","text":"营销口号不需要事实依据","why":"商业宣传仍需分析真实性。","correct":false}]},{"id":"T04-q4","stem":"论文为比较品牌而提及名称，商店把同名标志印到商品上。哪些区别应考虑？","options":[{"id":"2","text":"两者出现同一文字就必然同样处理","why":"忽略行为差异。","correct":false},{"id":"3","text":"只要标注引用来源就覆盖全部商品使用","why":"来源说明不自动产生商标许可。","correct":false},{"id":"1","text":"是否属于有关交易使用及适用例外","why":"与权利范围相关。","correct":true},{"id":"0","text":"实际使用的语境和功能","why":"不应仅凭出现文字作判断。","correct":true}]},{"id":"T04-q5","stem":"品牌保护团队收到一张相似包装照片。哪些行动更有依据？","options":[{"id":"3","text":"凭色调相似就宣布对方已被法院认定侵权","why":"把初步线索冒充裁判结果。","correct":false},{"id":"0","text":"补查销售商品、市场及使用主体","why":"单张图片事实有限。","correct":true},{"id":"1","text":"收集消费者认识与宣传资料","why":"便于分析混淆和联系。","correct":true},{"id":"2","text":"核实本方注册及在先权利情况","why":"先明确请求的权利基础。","correct":true}]}],"role":"平台品牌保护专员","scenario":"两家饮料店使用近似名称和相似杯身图案。另一商家则在完全不同的业务中使用相同单词，消费者联系尚不明确。","summary":"把标志、商品服务、交易使用和混淆可能放在一起看；词长相似或价格不同都不能单独决定结论。","variation":{"labels":["同名同类商品","近似词用于不相似商品"],"results":["TRIPS 对相同标志用于相同商品服务规定混淆推定。","不能直接照搬同名同类推定；还要核查驰名等其它路径是否适用。"]},"worked":"先把标志和商品放成两列，再找消费者认识证据。客服询问支持混淆分析，但完整结论仍需结合使用方式、权利范围及其它事实。"},{"id":"T05","title":"知名品牌能管到多远","case":"跨品类借名推广","pages":"7–10、19–20","scope":"巴黎公约、TRIPS 第 16.2–3 条与 WIPO 1999 联合建议的层次区分","nodes":[{"label":"相关公众","text":"TRIPS 要考虑相关领域公众对商标的认知，包括宣传获得的认知。","fact":"未在当地开店不直接证明当地无人知晓。"},{"label":"跨类条件","text":"第 16.3 条涉及注册商标、不类似商品的联系及利益可能受损。","fact":"“不卖鞋”不是完整分析。"},{"label":"建议与法律","text":"WIPO 联合建议讨论淡化和不当利用等标准；其性质应与条约、国内法区分。","fact":"建议本身不能直接替代当地法律结论。"}],"evidence":[{"label":"活动文案","text":"家具包装写“运动精神同源”，并突出另一品牌核心名称。"},{"label":"调研线索","text":"目标消费者熟悉该运动品牌，但没有双方合作合同。"}],"questions":[{"id":"T05-q1","stem":"家具公司借用知名运动商标，称品类不同即可放心。哪些判断适当？","options":[{"id":"1","text":"核查商业联系与利益可能受损","why":"不能只比较商品类别。","correct":true},{"id":"2","text":"只要商标著名便自动禁止任何字词提及","why":"保护不能无限扩大。","correct":false},{"id":"0","text":"不类似商品仍可能进入第 16.3 条分析","why":"跨类保护有条件。","correct":true},{"id":"3","text":"商品不同即可免除全部核查","why":"遗漏驰名保护路径。","correct":false}]},{"id":"T05-q2","stem":"品牌未在当地设店，但有大量当地相关公众接触的广告。哪些资料相关？","options":[{"id":"1","text":"相关领域公众的认识材料","why":"不应只统计整个国家所有人。","correct":true},{"id":"0","text":"广告传播带来的公众认知","why":"TRIPS 明确考虑宣传获得的认知。","correct":true},{"id":"2","text":"没有实体门店即不可能具有当地知名度","why":"宣传也可能建立认知。","correct":false},{"id":"3","text":"国外销售额足够大便无需当地事实","why":"仍需对应有关成员的认知。","correct":false}]},{"id":"T05-q3","stem":"团队把 WIPO 联合建议当成当地法院必然直接适用的法条。哪些纠正合理？","options":[{"id":"3","text":"因为是建议就没有任何比较研究价值","why":"仍有参考意义。","correct":false},{"id":"1","text":"核实当地法律是否采纳及怎样实施","why":"不能以建议替代国内依据。","correct":true},{"id":"2","text":"所有建议都自动修改国内法律","why":"不符合规范层次。","correct":false},{"id":"0","text":"说明其为联合建议的性质","why":"来源层级影响使用方式。","correct":true}]},{"id":"T05-q4","stem":"广告明确暗示与知名注册商标权利人合作，却无合作事实。哪些问题应核实？","options":[{"id":"2","text":"有关公众是否认识该商标","why":"知名度本身也需核查。","correct":true},{"id":"3","text":"只需查看新品牌设计费多少","why":"不能替代关键要件。","correct":false},{"id":"1","text":"权利人利益是否可能受损","why":"需要事实支持。","correct":true},{"id":"0","text":"是否产生商品与权利人的联系认识","why":"对应跨类保护条件。","correct":true}]},{"id":"T05-q5","stem":"初创企业准备使用与知名品牌相似的名称，哪些行动合理？","options":[{"id":"0","text":"分别检索注册、公众认知和实际使用","why":"不同证据支持不同问题。","correct":true},{"id":"1","text":"考虑改名或明确合规合作的可行性","why":"商业选择应建立在核查后。","correct":true},{"id":"3","text":"只要加上自己的公司后缀就绝对无风险","why":"整体联系与混淆仍需判断。","correct":false},{"id":"2","text":"承诺“没有恶意”便无须再审查","why":"主观表态不能替代客观条件。","correct":false}]}],"role":"品牌合作经理","scenario":"新家具品牌想使用知名运动品牌的核心名称，称“我们不卖鞋，所以不会有问题”。营销资料还暗示双方有合作。","summary":"驰名保护可能跨越类似商品，但要核查相关公众认知、联系与利益受损等条件；不能只看名气或品类。","variation":{"labels":["消费者认为存在商业联系","只有名字相同，认知与联系均无证据"],"results":["联系及权利人利益可能受损需进一步分析。","不能直接用“有名”代替全部条件；应补足证据。"]},"worked":"先看有关市场的相关公众，再看跨品类使用是否暗示联系、是否可能损害权利人利益。最后确认请求依据是条约实施规则还是建议中的政策标准。"},{"id":"T06","title":"商标能一直留着不用吗","case":"品牌仓库的年度检查","pages":"21–22","scope":"TRIPS 第 18、19 条最低标准；具体期限以保护地法律为准","nodes":[{"label":"注册续展","text":"TRIPS 要求初始及每次续展期限不少于 7 年，可无限次续展。","fact":"这不是要求每个成员都恰好采用 7 年。"},{"label":"不使用","text":"如要求使用维持，须持续至少 3 年未使用才可据此撤销，并考虑有效理由。","fact":"不能把一段短暂停售直接当满足撤销条件。"},{"label":"受控制使用","text":"他人在权利人控制下使用，可视为维持注册的使用。","fact":"应保存加盟控制与实际使用材料。"}],"evidence":[{"label":"品牌清单","text":"品牌甲停用 18 个月；品牌乙由总部控制品质的加盟店持续使用。"},{"label":"市场障碍","text":"某产品因政府进口限制暂时无法销售，已有对应文件。"}],"questions":[{"id":"T06-q1","stem":"公司认为 TRIPS 要求每次续展恰好七年。哪些纠正正确？","options":[{"id":"0","text":"七年是最低标准","why":"成员可以有更长期限。","correct":true},{"id":"1","text":"注册应可无限次续展","why":"不等于注册后无需维护。","correct":true},{"id":"3","text":"无限续展意味着不会因不使用受到挑战","why":"期限与使用条件不同。","correct":false},{"id":"2","text":"满七年必须放弃该品牌","why":"条约允许续展。","correct":false}]},{"id":"T06-q2","stem":"成员要求使用维持注册，品牌连续未用 18 个月。按本关条约底线，哪些判断成立？","options":[{"id":"2","text":"未用一天就应被撤销","why":"与本关最低门槛不符。","correct":false},{"id":"1","text":"仍应查本地制度与实际使用记录","why":"条约标准不替代具体规则。","correct":true},{"id":"3","text":"未满三年意味着其它撤销理由也全部排除","why":"题目只讨论不使用这一理由。","correct":false},{"id":"0","text":"尚未达到至少三年的不使用门槛","why":"不能仅据此期间满足条约撤销条件。","correct":true}]},{"id":"T06-q3","stem":"品牌因政府进口限制不能销售。哪些处理合适？","options":[{"id":"1","text":"区分外部障碍与自愿停用","why":"条文特别关注独立于权利人意志的障碍。","correct":true},{"id":"3","text":"存在限制即可永远免除使用管理","why":"障碍及期间仍需核查。","correct":false},{"id":"0","text":"保留限制及对使用影响的证明","why":"可能支持有效理由。","correct":true},{"id":"2","text":"任何经营不顺都当然等于法定有效理由","why":"需要具体判断。","correct":false}]},{"id":"T06-q4","stem":"商标由受权利人控制的加盟商使用。哪些说法正确？","options":[{"id":"1","text":"应保存控制及真实使用证据","why":"不能仅凭一纸空合同。","correct":true},{"id":"2","text":"只有权利人自己生产才算使用","why":"忽略受控制的他人使用。","correct":false},{"id":"0","text":"可作为维持注册的使用进行分析","why":"TRIPS 第 19.2 条有相应安排。","correct":true},{"id":"3","text":"任何未经许可的他人使用都自动维持注册","why":"控制条件不能省略。","correct":false}]},{"id":"T06-q5","stem":"品牌资产检查发现续展齐全，却无销售或许可使用档案。哪些补救方向合理？","options":[{"id":"0","text":"补查真实使用情况与期间","why":"续展不能替代使用证据。","correct":true},{"id":"1","text":"确认各保护地的具体要求","why":"不能把最低标准当统一期限。","correct":true},{"id":"3","text":"直接补做虚假销售凭据","why":"不能用伪造记录证明真实使用。","correct":false},{"id":"2","text":"分别管理续展和使用证明","why":"两套记录服务不同问题。","correct":true}]}],"role":"品牌资产管理员","scenario":"公司有多个注册品牌，其中一个长期未用，另一个由受控制的加盟商使用。管理层以为按时续展就不用再管。","summary":"续展解决注册期限，使用关系到维持条件；可以不断续展，不代表任何情况下都不会被撤销。","variation":{"labels":["只是管理层放着不用","政府进口限制阻碍使用"],"results":["需核对持续未使用期间及国内规则，不是自动永久保留。","可能构成独立于权利人意志的有效理由，应保留证明。"]},"worked":"分别建立到期日和使用记录两条线。续展记录证明期限管理，加盟使用或外部障碍资料支持使用维持分析，不能互相替代。"},{"id":"T07","title":"加盟用品牌，还是买下品牌","case":"加盟协议与商标转让","pages":"11–12、26、30–31","scope":"TRIPS 第 21 条；课件引中国商标法第 42 条及美国控制使用例子","nodes":[{"label":"许可","text":"明确使用范围、期限、地域及有关控制安排。","fact":"加盟合同不能仅凭标题判断有无转让。"},{"label":"转让","text":"核查权属变更和法定手续；TRIPS 允许与业务一并或分开转让。","fact":"出售商标不必在条约层面总与全部业务绑定。"},{"label":"关联商标","text":"课件所引中国规则要求一并处理规定范围的相同近似商标，防止混淆。","fact":"不能只因合同漏写就认为关联注册无需处理。"}],"evidence":[{"label":"加盟合同","text":"总部保留商标所有权，加盟商获得两年指定门店使用许可。"},{"label":"转让清单","text":"同一种商品上有两枚近似注册，交易清单暂只写一枚。"}],"questions":[{"id":"T07-q1","stem":"加盟协议明确总部保留所有权、门店获得两年使用权。哪些判断正确？","options":[{"id":"3","text":"加盟商因此无需再考虑期满","why":"两年期限仍有效。","correct":false},{"id":"2","text":"门店付费后便可任意转卖商标","why":"付款不改变题定权属。","correct":false},{"id":"1","text":"需遵守约定地域和用途","why":"许可范围决定获准使用。","correct":true},{"id":"0","text":"这是许可安排的线索","why":"合同没有把所有权交给门店。","correct":true}]},{"id":"T07-q2","stem":"企业按 TRIPS 第 21 条出售商标但保留生产业务。哪些说法成立？","options":[{"id":"3","text":"双方口头同意就自动满足所有国内手续","why":"需核实具体程序。","correct":false},{"id":"1","text":"仍需核查国内转让条件","why":"条约原则不取消办理要求。","correct":true},{"id":"2","text":"不卖工厂就绝对不能转让商标","why":"不符合条约框架。","correct":false},{"id":"0","text":"条约允许商标与业务分开转让","why":"不必总与全部业务绑定。","correct":true}]},{"id":"T07-q3","stem":"中国规则例题中，同类商品上的近似注册被遗漏在转让合同外。哪些处理适当？","options":[{"id":"0","text":"检查第 42 条要求一并转让的范围","why":"不能只按合同遗漏判断。","correct":true},{"id":"2","text":"只要买方愿意就能忽略关联商标规则","why":"私人意思不能替代法定要求。","correct":false},{"id":"1","text":"评估是否引起混淆或其它不良影响","why":"是课件所引审查问题。","correct":true},{"id":"3","text":"任何商标转让都无须向商标局申请","why":"与本例规则不符。","correct":false}]},{"id":"T07-q4","stem":"受控制的加盟使用被用于维持商标注册。哪些证据有意义？","options":[{"id":"2","text":"仅有合同封面而无执行资料就必然充分","why":"证据仍需对应事实。","correct":false},{"id":"1","text":"权利人的控制安排及落实情况","why":"对应本关控制使用条件。","correct":true},{"id":"3","text":"加盟门店数量自动证明合法控制","why":"数量不是控制本身。","correct":false},{"id":"0","text":"实际品牌使用记录","why":"证明不是空许可。","correct":true}]},{"id":"T07-q5","stem":"竞争企业请求政府强制许可另一企业商标。按 TRIPS 第 21 条，哪些判断正确？","options":[{"id":"3","text":"历史个案和政策建议不能替代现行条约文本","why":"应辨明来源层次。","correct":true},{"id":"1","text":"商标自愿许可与强制许可需分开","why":"禁强制不等于禁一切许可。","correct":true},{"id":"2","text":"专利可强制许可，商标必然同样可以","why":"不同权利对象规则不同。","correct":false},{"id":"0","text":"条约规定不得强制许可商标","why":"不能直接套用专利强制许可。","correct":true}]}],"role":"连锁品牌交易经理","scenario":"买方以为签加盟合同便拥有商标。随后双方拟真正转让品牌，却只列出一枚注册，遗漏同类商品上的近似注册。","summary":"许可通常让他人在约定范围内使用，转让改变权利归属；不同交易需要不同清单和程序。","variation":{"labels":["签订使用许可","办理商标转让"],"results":["加盟商应依范围使用，权利归属未因此转到加盟商。","进入权属变更及关联商标、程序审查，不能沿用许可清单。"]},"worked":"先读合同实际权利安排，再核对适用法手续。许可和转让不要混用；在中国规则例子中，还要把需要一并转让的关联商标纳入清单。"},{"id":"T08","title":"注册品牌，也要遵守包装规则","case":"公共健康包装审查","pages":"23–25","scope":"TRIPS 第 20 条“不合理妨碍”；课件澳大利亚烟草平装制度例子","nodes":[{"label":"权利与监管","text":"商标注册保护与产品包装监管是不同问题。","fact":"能排除他人使用，不等于能忽略健康警示。"},{"label":"条约用语","text":"TRIPS 第 20 条反对不合理的特殊妨碍，并非禁止所有要求。","fact":"论证重点包含措施和正当理由。"},{"label":"政策与事实","text":"评价公共健康和品牌功能应有制度与事实依据。","fact":"不能只凭个人支持或反对决定法律结论。"}],"evidence":[{"label":"监管要求","text":"本教学情境适用合法生效的健康警示及包装规则。"},{"label":"部门意见","text":"品牌部门想以商标证代替产品合规审查，直接沿用旧包装。"}],"questions":[{"id":"T08-q1","stem":"企业已有注册商标，拟拒绝题定有效健康警示要求。哪些判断正确？","options":[{"id":"0","text":"商标注册不能代替产品合规审查","why":"两个制度处理不同问题。","correct":true},{"id":"1","text":"需核对具体包装义务","why":"品牌权利并非监管豁免证。","correct":true},{"id":"3","text":"贴警示必然消灭商标注册","why":"展示限制不等于注册自动失效。","correct":false},{"id":"2","text":"注册证保证可按任何形式销售产品","why":"超出了权利含义。","correct":false}]},{"id":"T08-q2","stem":"团队引用 TRIPS 第 20 条反对所有展示要求。哪些纠正有依据？","options":[{"id":"0","text":"条文限定为不合理的妨碍","why":"不能删除该限定。","correct":true},{"id":"2","text":"凡要求改变字号都当然违反条约","why":"缺少完整分析。","correct":false},{"id":"3","text":"权利人不喜欢的要求即等于不合理","why":"主观不满不是充分标准。","correct":false},{"id":"1","text":"需要分析措施及其理由","why":"具体判断不能只靠名称。","correct":true}]},{"id":"T08-q3","stem":"包装方案同时出现生产企业标志与商品标志。按第 20 条，哪些说法合理？","options":[{"id":"2","text":"企业标志和商品标志在任何地方都不得共存","why":"与条文不符。","correct":false},{"id":"0","text":"条文对两者同时但不联结使用有说明","why":"不能概括为完全禁止同时展示。","correct":true},{"id":"1","text":"应核对具体要求是否符合条文描述","why":"事实结构影响判断。","correct":true},{"id":"3","text":"有两个标志便不再需要其它监管核查","why":"不能作此推论。","correct":false}]},{"id":"T08-q4","stem":"报告讨论烟草平装措施，哪些写法适合应试分析？","options":[{"id":"1","text":"区分实际措施、法律标准和个人政策评价","why":"避免把意见写成法律事实。","correct":true},{"id":"3","text":"把一个国家的包装安排当成全球统一要求","why":"需要法域限定。","correct":false},{"id":"2","text":"以“我赞成品牌自由”作为全部法律结论","why":"缺少规则与事实对应。","correct":false},{"id":"0","text":"说明保护品牌功能与公共健康之间的问题","why":"提出具体争点。","correct":true}]},{"id":"T08-q5","stem":"食品品牌遇到新的标签规则，哪些操作合理？","options":[{"id":"2","text":"记录措施对识别功能的具体影响","why":"为进一步分析提供事实。","correct":true},{"id":"0","text":"先核对规则适用产品和生效范围","why":"不能直接照搬烟草例子。","correct":true},{"id":"1","text":"同时审查标签真实性与商标展示","why":"可能涉及不同义务。","correct":true},{"id":"3","text":"只凭原包装曾经使用就永远沿用","why":"既有使用不自动排除新规则。","correct":false}]}],"role":"产品包装合规经理","scenario":"受监管产品需要按规定显示健康警示和统一包装。品牌部门认为取得注册商标就能拒绝全部包装限制。","summary":"商标排他保护不等于不受产品监管；特殊要求是否不合理，需要结合规则、理由和具体措施分析。","variation":{"labels":["已有商标注册","发现规则要求改变展示方式"],"results":["继续核查产品监管；注册本身未授权违反包装规定。","分别分析具体要求、理由和条约标准，不能只看标志是否缩小。"]},"worked":"先区分“谁能用品牌”和“产品怎样合法上市”。第 20 条关注不合理妨碍，争议需围绕措施及理由展开，不能把任何监管都预先视为违法。"},{"id":"T09","title":"“某某风格”能绕开产地保护吗","case":"酒类与茶叶的新标签","pages":"32–43","scope":"TRIPS 第 22–24 条；题目假设有关地理标志获保护且无第 24 条例外","nodes":[{"label":"产地联系","text":"质量、声誉或其它特征本质上归因于地理来源。","fact":"一般地名不自动都满足这一条件。"},{"label":"一般保护","text":"防止误导真实来源以及有关不正当竞争。","fact":"文字真实也可能在整体呈现上误导来源。"},{"label":"酒类特别保护","text":"受保护酒类地理标志用于非该产地产品时，真实来源或“类型”等措辞不当然免责。","fact":"例外仍需另查，不能把特别保护说成毫无限定。"}],"evidence":[{"label":"酒标方案","text":"非某受保护葡萄酒产地生产，标签写该产地名并加“风格”，另注明真实产地。"},{"label":"茶叶包装","text":"茶叶产自别处，包装图片与文字使公众以为来自知名产区。"}],"questions":[{"id":"T09-q1","stem":"一种商品的声誉主要源自特定地区。哪些资料支持地理标志分析？","options":[{"id":"2","text":"包装采用地图就自动具备全部保护条件","why":"地图不能替代条件证明。","correct":false},{"id":"3","text":"所有地名都必然属于受保护地理标志","why":"需要商品联系及适用规则。","correct":false},{"id":"1","text":"真实生产来源资料","why":"需要核查实际产地。","correct":true},{"id":"0","text":"商品与该地区声誉的联系","why":"对应地理归因条件。","correct":true}]},{"id":"T09-q2","stem":"非产区茶叶被包装成来自名产区，消费者因此误认。哪些问题相关？","options":[{"id":"3","text":"小字写真产地就必然排除整体误导","why":"还需结合完整呈现。","correct":false},{"id":"0","text":"对真实来源的误导","why":"与第 22 条一般保护对应。","correct":true},{"id":"1","text":"可能涉及不正当竞争的呈现","why":"不能只看单个词是否真实。","correct":true},{"id":"2","text":"只要销售者住在该地区就能冒充商品产地","why":"经营者住址不等于商品来源。","correct":false}]},{"id":"T09-q3","stem":"无相关例外，非产地葡萄酒使用受保护酒类地理标志并写“风格”。哪些判断成立？","options":[{"id":"1","text":"注明真实产地也不当然免责","why":"特别保护不限于一般误导门槛。","correct":true},{"id":"3","text":"翻译产地名就一定绕开保护","why":"条文也考虑翻译使用。","correct":false},{"id":"2","text":"只要消费者没被误导就必然允许","why":"忽略酒类特别保护。","correct":false},{"id":"0","text":"加“风格”不能当然排除第 23 条问题","why":"条文明确涵盖类似表述。","correct":true}]},{"id":"T09-q4","stem":"两个葡萄酒产区使用同音异义地理标志。哪些做法符合本关？","options":[{"id":"2","text":"所有同名产区一律只能保留一个","why":"与条文安排不符。","correct":false},{"id":"0","text":"需要适当区分并避免误导消费者","why":"第 23.3 条要求处理区分条件。","correct":true},{"id":"3","text":"存在同名就允许任意虚构来源","why":"真实与不误导要求仍重要。","correct":false},{"id":"1","text":"兼顾有关生产者的公平待遇","why":"不能简单只按先到者一刀切。","correct":true}]},{"id":"T09-q5","stem":"同事引用课件中“地理标志不应视为知识产权”的评价，主张无需审查标签。哪些纠正合理？","options":[{"id":"2","text":"注意例外与具体商品类别","why":"不能把一条原则绝对化。","correct":true},{"id":"3","text":"政策讨论可以直接替代经营合规结论","why":"缺少规则和事实对应。","correct":false},{"id":"1","text":"仍需核查第 22、23 条及当地实施","why":"真实使用需要适用依据。","correct":true},{"id":"0","text":"区分教师政策观点与 TRIPS 规范安排","why":"个人评价不能取消规则。","correct":true}]}],"role":"食品酒类进口经理","scenario":"商家拟给非该产地葡萄酒标上受保护产地名加“风格”，又想把普通茶叶包装成来自名产区的产品。","summary":"地理标志把商品特征或声誉与产地连接；葡萄酒和烈酒有特别保护，写明真实产地或加“风格”不当然解决问题。","variation":{"labels":["普通商品的来源表示","受保护葡萄酒地理标志"],"results":["重点分析是否误导以及不正当竞争；还要核查地理联系。","进入特别保护路径，不以误导为同样的必要门槛；题目须排除适用例外。"]},"worked":"先确认标志和商品类别。对茶叶看来源误导，对葡萄酒看特别保护和例外；“风格”不是各类商品通用的免责工具。"},{"id":"P01","title":"杯子的造型与保温结构","case":"新产品拆解会议","pages":"2–5、10","scope":"TRIPS 第 25、26 条工业品外观设计；国内保护路径有差别","nodes":[{"label":"外观要件","text":"独立创作且新或原创；成员可排除主要由技术或功能决定的设计。","fact":"杯身视觉造型与隔热原理不同。"},{"label":"商业利用","text":"保护可针对商业性制造、销售、进口复制或实质复制设计的产品。","fact":"不是任何相似外形都无需比较。"},{"label":"期限与路径","text":"TRIPS 保护期限总计至少 10 年；具体登记及保护形式看当地制度。","fact":"不要把一国登记期限当全球统一规则。"}],"evidence":[{"label":"设计图","text":"杯身有独特轮廓；内部隔热层另有技术说明。"},{"label":"申报草案","text":"申请材料仅展示外形，宣传却声称“已保护全部保温方法”。"}],"questions":[{"id":"P01-q1","stem":"保温杯同时有独特造型和新隔热结构。哪些分类正确？","options":[{"id":"2","text":"外观登记自动垄断所有保温原理","why":"超出保护对象。","correct":false},{"id":"3","text":"只要产品有功能便绝对不能保护任何外观","why":"还需区分具体特征。","correct":false},{"id":"0","text":"杯身视觉造型可进入外观设计分析","why":"对象是外观表现。","correct":true},{"id":"1","text":"隔热技术需要另查技术保护路径","why":"外观申请不直接覆盖原理。","correct":true}]},{"id":"P01-q2","stem":"设计师照搬已有杯形，仅更换说明文案。哪些问题应检查？","options":[{"id":"0","text":"是否独立创作且新或原创","why":"对应第 25 条条件。","correct":true},{"id":"1","text":"与已知设计是否有显著区别","why":"条文允许成员据此判断。","correct":true},{"id":"3","text":"文案不同便必然使杯形成为新设计","why":"对象仍是杯形设计。","correct":false},{"id":"2","text":"写上原创声明就证明满足要件","why":"声明不能替代事实。","correct":false}]},{"id":"P01-q3","stem":"竞争企业商业性进口实质复制受保护外观的杯子。哪些行为相关？","options":[{"id":"1","text":"与受保护设计的复制程度","why":"应确认是否复制或实质复制。","correct":true},{"id":"3","text":"只有亲手制造者才可能需要许可","why":"销售与进口也相关。","correct":false},{"id":"0","text":"商业性进口","why":"第 26 条涉及进口行为。","correct":true},{"id":"2","text":"进口行为不在外观保护范围内","why":"与条约框架不符。","correct":false}]},{"id":"P01-q4","stem":"团队将 TRIPS 外观最低期限写成“所有国家恰好十年”。哪些纠正成立？","options":[{"id":"2","text":"十年届满前绝不需要管理手续","why":"具体制度可能要求续展等事项。","correct":false},{"id":"1","text":"具体登记和续展规则需另查","why":"条约底线不是完整流程。","correct":true},{"id":"0","text":"至少十年是最低总期限","why":"不等于所有成员相同。","correct":true},{"id":"3","text":"未登记设计在任何国家都没有保护路径","why":"国内制度可能不同。","correct":false}]},{"id":"P01-q5","stem":"服装品牌为季节性花纹选择保护方式。哪些考虑有依据？","options":[{"id":"2","text":"设计的新颖或原创及独立创作证据","why":"保护路径仍需基础事实。","correct":true},{"id":"0","text":"当地外观与版权制度的适用","why":"TRIPS 对纺织品设计允许不同实现方式。","correct":true},{"id":"1","text":"申请成本和时间对产品周期的影响","why":"与是否实际寻求保护有关。","correct":true},{"id":"3","text":"短期产品当然无需考虑他人设计权","why":"生命周期短不代表免核查。","correct":false}]}],"role":"产品开发经理","scenario":"团队推出独特杯身造型，又发明新的隔热结构。设计师希望一份外观申请同时覆盖外形和全部技术原理。","summary":"外观设计主要针对产品外观；技术功能要另外分析。把产品拆开，才能选对保护对象。","variation":{"labels":["争议集中在杯身造型","争议集中在隔热原理"],"results":["比较受保护外观及复制程度，并核实商业利用。","转向技术方案和其它保护路径，不能仅凭外观文件覆盖原理。"]},"worked":"先画出产品外层与内部结构。外观文件围绕视觉设计核查；隔热方法要另看专利等条件，不能让产品是一件物品就变成只有一类权利。"},{"id":"P02","title":"PCT 申请不是全球专利","case":"传感器的海外布局","pages":"6、11","scope":"巴黎公约专利独立性；PCT 国际申请与国家阶段","nodes":[{"label":"地域性","text":"不同国家对同一发明授予的专利独立。","fact":"一个市场的授权不证明另一个市场已有权利。"},{"label":"国际阶段","text":"国际申请帮助处理跨国申请程序。","fact":"申请号不是全球授权证书。"},{"label":"后续阶段","text":"需要在相关期限内办理国家或地区阶段，接受审查。","fact":"市场选择、费用和期限仍要管理。"}],"evidence":[{"label":"申请回执","text":"文件标题为国际申请，已有申请号；没有各市场授权记录。"},{"label":"上线材料","text":"官网计划标注“所有国家均受本公司专利保护”。"}],"questions":[{"id":"P02-q1","stem":"企业提交 PCT 后宣称全球授权。哪些纠正正确？","options":[{"id":"3","text":"提交一次后无需考虑任何后续期限","why":"仍需办理后续阶段。","correct":false},{"id":"2","text":"国际申请号本身是全球排他权证书","why":"不存在这种直接推论。","correct":false},{"id":"1","text":"宣传应区分申请中与已授权","why":"不能把程序状态夸大。","correct":true},{"id":"0","text":"PCT 提交不等于各国已经授权","why":"后续由相关主管机关审查。","correct":true}]},{"id":"P02-q2","stem":"同一技术甲国获准、乙国被驳回。哪些判断适当？","options":[{"id":"3","text":"乙国驳回当然取消甲国权利","why":"应分别核查。","correct":false},{"id":"0","text":"两地专利独立分析","why":"不能仅因结果不同就认定无效。","correct":true},{"id":"2","text":"甲国授权必然推翻乙国决定","why":"独立性不支持该推论。","correct":false},{"id":"1","text":"检查乙国驳回理由和当地程序","why":"需针对具体问题处理。","correct":true}]},{"id":"P02-q3","stem":"团队进入目标国家阶段。哪些事项需要管理？","options":[{"id":"1","text":"当地实质审查和权利范围","why":"最终结果由有关主管机关处理。","correct":true},{"id":"3","text":"所有市场的授权结果可不加区分地合并","why":"会误报状态。","correct":false},{"id":"0","text":"相关期限、材料及费用","why":"国际申请未取消这些事务。","correct":true},{"id":"2","text":"只需保存国际宣传海报","why":"不能代替程序材料。","correct":false}]},{"id":"P02-q4","stem":"公司在甲国有专利，却拟直接起诉乙国的制造行为。哪些事实须先核实？","options":[{"id":"3","text":"有 PCT 就不必核对乙国保护","why":"重复混淆程序与授权。","correct":false},{"id":"0","text":"乙国是否存在可主张的有效权利","why":"地域是关键。","correct":true},{"id":"1","text":"被诉行为和权利范围","why":"不是技术相似便足够。","correct":true},{"id":"2","text":"只看甲国专利证颜色和版式","why":"与乙国权利基础无关。","correct":false}]},{"id":"P02-q5","stem":"投资材料列出各国专利组合。哪些表述更准确？","options":[{"id":"3","text":"把全部申请数量称为已授权数量","why":"混淆状态。","correct":false},{"id":"2","text":"保留可核验的申请或授权编号","why":"便于追溯。","correct":true},{"id":"1","text":"说明有关国家或地区","why":"避免暗示全球无差别覆盖。","correct":true},{"id":"0","text":"分别标记申请、授权和失效状态","why":"让读者看清权利结果。","correct":true}]}],"role":"研发公司的出海负责人","scenario":"团队已提交 PCT 申请，销售资料却写“全球专利已授权”。目标市场的后续手续尚未办理。","summary":"PCT 是国际申请途径；是否授予保护仍由相关国家或地区的主管机关决定。","variation":{"labels":["只有国际申请回执","某目标市场已授权"],"results":["应准确写明申请状态，不能宣称全球已授权。","可说明该市场及其范围，仍需分别核对其它市场。"]},"worked":"把“申请途径”和“权利结果”拆开。逐个市场记录申请、审查、授权和有效状态，宣传文字只能对应已有证据。"},{"id":"P03","title":"新点子能申请发明专利吗","case":"设备方案的三项检查","pages":"18","scope":"TRIPS 第 27.1 条：新颖性、创造性、工业适用性","nodes":[{"label":"新颖性","text":"对照适用规则下的现有技术，判断方案是否已被公开。","fact":"已有文献的内容与公开时间需要核查。"},{"label":"创造性","text":"分析相对现有技术的技术贡献，而非只看名称新不新。","fact":"常规改动与有意义的技术进步需区分。"},{"label":"工业适用性","text":"方案须能够用于产业实践。","fact":"可运行支持应用，但不自动证明前两个条件。"}],"evidence":[{"label":"研发样机","text":"样机可以稳定运行，并有测试记录。"},{"label":"检索结果","text":"旧文献存在近似结构，差异和公开日期尚未分析。"}],"questions":[{"id":"P03-q1","stem":"一台设备运行稳定，但结构早已在符合题定现有技术标准的文献中完整公开。哪些判断适当？","options":[{"id":"3","text":"实现商业销售便保证专利获准","why":"销售不等于条件全部满足。","correct":false},{"id":"2","text":"投入研发资金多即可替代新颖性","why":"成本不是该要件。","correct":false},{"id":"1","text":"需把申请方案与公开内容具体比较","why":"不能只比较产品名称。","correct":true},{"id":"0","text":"能运行不能自动解决新颖性问题","why":"条件相互独立。","correct":true}]},{"id":"P03-q2","stem":"团队把旧装置换颜色，声称创造性明显提高。哪些材料更相关？","options":[{"id":"2","text":"只统计广告点击量","why":"不能直接证明技术贡献。","correct":false},{"id":"1","text":"差异产生的技术效果及现有技术启示","why":"有助判断是否只是常规选择。","correct":true},{"id":"3","text":"只把方案名称改成智能设备","why":"名称不能替代技术事实。","correct":false},{"id":"0","text":"技术特征差异","why":"创造性分析需要具体技术内容。","correct":true}]},{"id":"P03-q3","stem":"研发报告分别有检索文献、差异分析和应用测试。哪些对应合理？","options":[{"id":"3","text":"任意一项优秀即可免除其余条件","why":"三个条件都需审查。","correct":false},{"id":"0","text":"公开文献用于新颖性等比较","why":"要结合公开内容和时间。","correct":true},{"id":"2","text":"差异与效果用于创造性分析","why":"需结合技术背景。","correct":true},{"id":"1","text":"应用测试支持工业适用性分析","why":"但不是全部条件的证明。","correct":true}]},{"id":"P03-q4","stem":"团队问是否必须本地制造才享有专利。按第 27.1 条，哪些说法正确？","options":[{"id":"2","text":"外国完成的发明一律不得获专利","why":"与条约要求相悖。","correct":false},{"id":"0","text":"条约规定进口与本地生产不应受到所述歧视","why":"需留意条文前提与例外。","correct":true},{"id":"1","text":"发明地点与技术领域也有相关非歧视要求","why":"属于本条框架。","correct":true},{"id":"3","text":"所有对象因此都无条件可专利","why":"第 27 条仍有条件与允许排除。","correct":false}]},{"id":"P03-q5","stem":"创业者要公开演示未申请方案。哪些规划有依据？","options":[{"id":"1","text":"保存公开时间、内容与申请安排","why":"重要时间事实需记录。","correct":true},{"id":"2","text":"所有国家都有无限期公开宽限","why":"不能作此假设。","correct":false},{"id":"0","text":"先评估公开对目标法域新颖性的影响","why":"不同制度的例外需核查。","correct":true},{"id":"3","text":"保密只与商业秘密有关，与专利规划无关","why":"公开可能影响专利条件。","correct":false}]}],"role":"技术评审负责人","scenario":"研发团队做出一个制造设备方案。它能运行，但部分结构已在旧文献中公开；改进是否超出常规仍待分析。","summary":"能做出来、此前没有完全相同方案、具有创造性，是不同问题；三个条件要分别找证据。","variation":{"labels":["只有“样机能用”","有检索、差异与技术效果证据"],"results":["获得应用方面的线索，仍缺新颖性和创造性分析。","可以分别对应三个条件，仍需完整审查。"]},"worked":"将资料放入三个格子：测试支持可应用；文献支持公开比较；差异和效果支持创造性。不能用一份成功测试报告回答全部问题。"},{"id":"P04","title":"不同发明，保护路线一样吗","case":"农业与医疗技术评审","pages":"19、21","scope":"TRIPS 第 27.2–3 条允许的排除；植物品种保护要求","nodes":[{"label":"医疗方法","text":"成员可排除人或动物的诊断、治疗和外科方法。","fact":"方法与药品产品不能不加区分地混为一类。"},{"label":"生物对象","text":"植物动物、微生物及生物过程的条文位置不同。","fact":"“都是生物”不能代替分类。"},{"label":"品种与公共利益","text":"植物品种须通过专利、有效专门制度或组合保护；公共秩序排除有条件。","fact":"商业利用违法本身不是条约排除的充分理由。"}],"evidence":[{"label":"研发清单","text":"外科步骤、微生物生产工艺、适合干旱地区的新品种。"},{"label":"目标市场","text":"尚未确认各市场是否采用条约允许的排除及具体保护路径。"}],"questions":[{"id":"P04-q1","stem":"企业提出外科治疗方法。按 TRIPS，哪些说法成立？","options":[{"id":"3","text":"所有成员必须一律排除","why":"误读了允许性表述。","correct":false},{"id":"1","text":"应查看目标成员实际规定","why":"不能由条约许可推定已排除。","correct":true},{"id":"0","text":"成员可以在规定范围内排除该类方法","why":"注意是允许的制度选择。","correct":true},{"id":"2","text":"所有医疗产品因此都不得申请专利","why":"方法与产品不同。","correct":false}]},{"id":"P04-q2","stem":"公司获得植物新品种，哪些制度安排符合条约框架？","options":[{"id":"2","text":"将两种方式结合","why":"条约允许组合。","correct":true},{"id":"1","text":"采用有效的专门保护制度","why":"不必只能采用专利。","correct":true},{"id":"3","text":"成员可完全不提供任何有效品种保护","why":"不符合品种保护要求。","correct":false},{"id":"0","text":"采用专利保护","why":"是条约允许路径之一。","correct":true}]},{"id":"P04-q3","stem":"团队把植物、动物和微生物一律写为可全部排除。哪些纠正适当？","options":[{"id":"3","text":"条约排除对象不需核对具体权利要求","why":"对象应结合申请内容辨认。","correct":false},{"id":"1","text":"生产过程也要区分其性质","why":"基本生物、非生物和微生物过程有区别。","correct":true},{"id":"2","text":"所有生物相关项目只需同一结论","why":"分类会影响规则。","correct":false},{"id":"0","text":"微生物在有关排除条文中有区分","why":"不能直接纳入植物动物的同一表述。","correct":true}]},{"id":"P04-q4","stem":"某方案商业利用被国内法规禁止，政府想直接援引公共秩序排除。哪些分析正确？","options":[{"id":"2","text":"禁止销售就自动失去任何专利可能","why":"混淆监管和专利条件。","correct":false},{"id":"0","text":"仅有法律禁止不足以完成条约条件分析","why":"第 27.2 条明确限制这一推论。","correct":true},{"id":"3","text":"只要有商业价值便不能有任何公共利益限制","why":"同样过于绝对。","correct":false},{"id":"1","text":"须核查保护公共秩序或道德等必要性","why":"需要对应条文规定。","correct":true}]},{"id":"P04-q5","stem":"跨国研发团队准备保护三类不同生物技术成果。哪些工作合理？","options":[{"id":"3","text":"只照抄别国驳回结论作为全球结论","why":"缺少适用范围核查。","correct":false},{"id":"1","text":"列出各目标法域的制度选择","why":"条约空间可能产生差异。","correct":true},{"id":"0","text":"按对象与权利要求分别分类","why":"避免用产业名称代替对象。","correct":true},{"id":"2","text":"结合公开安排与品种保护路径制定计划","why":"保护方法应匹配成果。","correct":true}]}],"role":"研发组合负责人","scenario":"公司同时研究外科治疗方法、微生物工艺和新品种。管理层希望用“生物技术”一个标签决定所有项目。","summary":"条约允许排除某些对象，但不是要求所有成员一律排除；植物品种还须有规定的有效保护路径。","variation":{"labels":["对象是治疗方法","对象是植物品种"],"results":["核查目标成员是否采取允许的排除，不直接推定全球一致。","确认专利、有效专门制度或两者组合的保护路径。"]},"worked":"先按对象分类，再查成员选择。条约的“可以排除”不等于所有国家已排除；品种保护也不等于只剩一种专利方案。"},{"id":"P05","title":"软件的技术效果在哪里","case":"商业程序与设备控制","pages":"19–20","scope":"EPC 第 52 条及 EPO 软件技术特征框架；不作全球统一结论","nodes":[{"label":"程序本身","text":"EPC 对程序作为其本身作排除，不能直接解释为所有软件都不可能保护。","fact":"程序与具体技术应用应区分。"},{"label":"进一步技术效果","text":"超过软硬件正常物理交互，例如控制技术过程或内部运行。","fact":"控制制动与只计算商业优惠不同。"},{"label":"继续审查","text":"跨过技术特征门槛不等于已经满足新颖性和创造性。","fact":"“有技术效果”不是授权保证。"}],"evidence":[{"label":"程序甲","text":"按营销人员设定的优惠规则计算折扣，没有其它技术作用事实。"},{"label":"程序乙","text":"根据传感器数据调整制动过程，有技术控制说明。"}],"questions":[{"id":"P05-q1","stem":"申请理由只有“运行时产生电流”。按本关欧洲框架，哪些判断正确？","options":[{"id":"2","text":"程序运行便自动获得专利资格","why":"理由不足。","correct":false},{"id":"3","text":"没有机械零件就不可能有技术效果","why":"内部计算机功能也可能相关。","correct":false},{"id":"1","text":"需要说明具体技术作用","why":"对应技术特征分析。","correct":true},{"id":"0","text":"正常物理交互不足以证明进一步技术效果","why":"不能仅靠通电事实。","correct":true}]},{"id":"P05-q2","stem":"程序控制车辆制动过程。哪些分析适当？","options":[{"id":"3","text":"所有软件都由 EPC 无例外排除","why":"忽略“作为其本身”的限定。","correct":false},{"id":"0","text":"技术过程控制可支持进一步技术效果","why":"要结合具体方案。","correct":true},{"id":"2","text":"一旦控制设备就保证最终授权","why":"遗漏其它要求。","correct":false},{"id":"1","text":"仍需审查新颖性与创造性","why":"技术特征并非全部条件。","correct":true}]},{"id":"P05-q3","stem":"折扣程序只把既有商业规则自动化，没有其它技术事实。哪些说法稳妥？","options":[{"id":"2","text":"只因计算更快就必然满足所有技术要求","why":"速度不能在该事实下直接证明全部条件。","correct":false},{"id":"1","text":"应区分商业规则与具体技术实现","why":"不能只看产品名字。","correct":true},{"id":"3","text":"用户多就能替代创造性分析","why":"市场规模不是技术创造性的证明。","correct":false},{"id":"0","text":"自动化本身不能直接证明进一步技术效果","why":"还需其它技术考虑。","correct":true}]},{"id":"P05-q4","stem":"团队把欧洲分析直接写成世界各地统一规则。哪些纠正有依据？","options":[{"id":"1","text":"其它目标市场需另外核查","why":"专利条件并非全球完全一致。","correct":true},{"id":"0","text":"限定 EPC 与 EPO 的适用语境","why":"法域必须说清。","correct":true},{"id":"2","text":"所有国家必须逐字采用 EPO 指南","why":"无此依据。","correct":false},{"id":"3","text":"欧洲技术门槛通过就等于各国授权","why":"重复混淆制度和结果。","correct":false}]},{"id":"P05-q5","stem":"程序改善计算机内部内存分配。申请准备应关注哪些材料？","options":[{"id":"3","text":"只提供融资估值即可","why":"无法替代技术说明。","correct":false},{"id":"0","text":"内部运行的技术考虑及效果","why":"可能支持技术特征。","correct":true},{"id":"2","text":"权利要求如何体现这些特征","why":"不能只写宣传性效果。","correct":true},{"id":"1","text":"与现有技术相比的具体区别","why":"用于后续新颖性与创造性分析。","correct":true}]}],"role":"软件研发负责人","scenario":"一个程序只计算商店折扣，另一个控制机器的制动过程。团队认为“都在电脑上运行”就足以满足欧洲技术要求。","summary":"在欧洲框架下，程序本身的排除有具体边界；普通通电运行不够，要看进一步技术效果，并继续审查其它条件。","variation":{"labels":["理由仅为“电脑会通电”","能说明技术过程控制"],"results":["正常物理交互不足以证明进一步技术效果。","可支持技术特征分析，仍要核查权利要求及其它专利条件。"]},"worked":"把商业目标和技术作用拆开。不能只说运行更方便；应指出程序对哪个技术过程或计算机内部功能产生怎样的作用，再继续审查新颖性和创造性。"},{"id":"P06","title":"专利能禁止什么，算多久","case":"设备许可谈判","pages":"22、31","scope":"TRIPS 第 28、32、33 条；权利范围需结合有效权利要求和适用例外","nodes":[{"label":"产品与方法","text":"产品权利涉及制造、使用、许诺销售、销售、相关进口；方法还涉及使用方法及直接所得产品。","fact":"外包制造不使销售或进口当然无关。"},{"label":"期限","text":"TRIPS 期限不得在申请日起 20 年届满前结束。","fact":"不能把授权日当然当作这一最低期限起点。"},{"label":"复核与许可","text":"撤销或丧失专利应有司法审查机会；专利可许可或转让。","fact":"许可期限不能凭谈判任意改变法定专利期限。"}],"evidence":[{"label":"谈判表","text":"产品制造、销售、进口都在计划中，方法使用尚未确认。"},{"label":"条款草稿","text":"写成“授权日起永久保护，撤销决定不得审查”。"}],"questions":[{"id":"P06-q1","stem":"工厂只进口受有效产品专利覆盖的产品，未经同意且无例外。哪些说法成立？","options":[{"id":"2","text":"未亲手制造就当然不涉及专利","why":"忽略进口等权利。","correct":false},{"id":"0","text":"进口属于需核查的权利行为","why":"不是只有制造才相关。","correct":true},{"id":"3","text":"购买国外货物必然排除本地专利","why":"还需当地权利与相关规则。","correct":false},{"id":"1","text":"应核实产品是否落入权利范围","why":"有专利仍需具体对应。","correct":true}]},{"id":"P06-q2","stem":"竞争企业使用专利方法，并销售由其直接获得的产品。哪些核查相关？","options":[{"id":"0","text":"是否未经许可使用该方法","why":"方法使用是核心行为。","correct":true},{"id":"1","text":"直接所得产品的有关销售行为","why":"第 28 条也涵盖该方向。","correct":true},{"id":"2","text":"方法专利只能限制机器外观","why":"对象错误。","correct":false},{"id":"3","text":"成品离开工厂就自动不再涉及方法专利","why":"不能如此推定。","correct":false}]},{"id":"P06-q3","stem":"申请日为 2020 年，授权日为 2024 年。仅按 TRIPS 第 33 条一般最低期限，哪些判断正确？","options":[{"id":"1","text":"一般最低期限按申请日起 20 年考虑","why":"实际状态及其它制度仍需查。","correct":true},{"id":"2","text":"条约当然要求从 2024 年起再算 20 年","why":"起点错误。","correct":false},{"id":"0","text":"起点是申请日","why":"不是默认授权日。","correct":true},{"id":"3","text":"取得授权意味着产品已被监管机构批准销售","why":"专利与上市监管不同。","correct":false}]},{"id":"P06-q4","stem":"专利被撤销，机关称完全不存在司法审查机会。哪些说法有依据？","options":[{"id":"2","text":"专利一经授权永远不能被撤销","why":"授权不排除无效等问题。","correct":false},{"id":"0","text":"TRIPS 要求提供司法审查机会","why":"第 32 条明确这一点。","correct":true},{"id":"3","text":"提出复核就自动证明专利有效","why":"仍需判断理由。","correct":false},{"id":"1","text":"复核机会不等于必然撤销原决定","why":"程序保障不同于实体结果。","correct":true}]},{"id":"P06-q5","stem":"公司获得设备专利后准备销售受监管产品。哪些检查仍有必要？","options":[{"id":"1","text":"其它有效权利及实际实施范围","why":"有自己的专利不保证不触及他人权利。","correct":true},{"id":"0","text":"相关产品监管许可","why":"专利不代替上市要求。","correct":true},{"id":"2","text":"本方专利有效状态与许可安排","why":"商业实施需准确权利资料。","correct":true},{"id":"3","text":"以专利证覆盖全部制造销售合规义务","why":"权利和监管不能混用。","correct":false}]}],"role":"工厂技术许可经理","scenario":"工厂要制造某产品，也可能采用一个受专利保护的方法。谈判时，对方把保护期写成授权日起 20 年，并称撤销无需复核。","summary":"区分产品与方法权利，核对申请日起算的条约期限和撤销审查；拥有专利也不等于获得产品上市许可。","variation":{"labels":["争议对象是产品专利","争议对象是方法专利"],"results":["逐项检查制造、使用、销售与进口等行为。","还要分析是否使用方法及产品是否由该方法直接获得。"]},"worked":"先圈出权利要求与行为，再看有效状态和例外。期限用申请日起的条约标准分析，不把取得证书或上市时间当起点，也不把许可合同当修改法定期限的工具。"},{"id":"P07","title":"未经同意使用专利，需要什么条件","case":"公共供应的许可方案","pages":"7–9、23–25","scope":"TRIPS 第 31 条一般框架；不等于企业可自行宣布强制许可","nodes":[{"label":"先行努力","text":"一般需先按合理商业条件争取授权且合理期间未成功；紧急等情形可豁免该要求。","fact":"是否豁免必须对应规定情形。"},{"label":"范围与性质","text":"逐案考虑，限于授权目的的范围和期限，通常非独占且转让受限。","fact":"不是得到永久独占权。"},{"label":"报酬与审查","text":"仍需考虑通知、适当报酬及授权和报酬的独立审查。","fact":"紧急不直接等于免费且无人可复核。"}],"evidence":[{"label":"项目需求","text":"短期供应出现缺口；企业尚未说明是否符合紧急情形。"},{"label":"方案缺项","text":"没有主管授权文件、生产范围、期限或报酬安排。"}],"questions":[{"id":"P07-q1","stem":"企业自行宣布因为短缺便获得强制许可。哪些判断正确？","options":[{"id":"3","text":"只需发一份新闻稿即可开始使用","why":"宣传不是许可决定。","correct":false},{"id":"1","text":"应明确范围及期限","why":"使用受授权目的限制。","correct":true},{"id":"0","text":"需核实有权授权与适用条件","why":"企业声明不能代替制度程序。","correct":true},{"id":"2","text":"市场需求高就自动产生许可","why":"缺少授权依据。","correct":false}]},{"id":"P07-q2","stem":"一般情形下寻求第 31 条许可，哪些资料有意义？","options":[{"id":"3","text":"只需证明许可费不是自己理想价格","why":"不直接证明条文要求满足。","correct":false},{"id":"0","text":"按合理商业条件寻求许可的努力","why":"与先行协商条件相关。","correct":true},{"id":"2","text":"从未沟通却只声称对方一定拒绝","why":"推测不能代替事实。","correct":false},{"id":"1","text":"在合理期间未成功的记录","why":"帮助说明该条件。","correct":true}]},{"id":"P07-q3","stem":"题定国家紧急情况适用事先协商豁免。哪些说法成立？","options":[{"id":"1","text":"仍应按规定通知权利人","why":"紧急情形下尽快合理通知仍重要。","correct":true},{"id":"2","text":"报酬及范围等仍需分析","why":"豁免不是无偿无限使用。","correct":true},{"id":"3","text":"可把短期许可自动改成永久独占","why":"与性质和目的限制冲突。","correct":false},{"id":"0","text":"该豁免不等于取消全部条件","why":"需逐项辨明规则。","correct":true}]},{"id":"P07-q4","stem":"许可文件把使用权写成可任意单独转售的永久独占权。哪些问题应指出？","options":[{"id":"3","text":"只要支付报酬就可省略所有限制","why":"报酬不是唯一要求。","correct":false},{"id":"2","text":"主管机关授权后任何文字都符合条约","why":"授权仍受条件约束。","correct":false},{"id":"0","text":"第 31 条要求非独占性质","why":"不能这样替代权利人地位。","correct":true},{"id":"1","text":"转让与范围、期间受到限制","why":"不是可任意交易的完整专利。","correct":true}]},{"id":"P07-q5","stem":"半导体技术需要非自愿许可。按第 31 条，哪些方向符合特别限制？","options":[{"id":"3","text":"只需竞争者单方指称垄断","why":"不能代替正式程序认定。","correct":false},{"id":"1","text":"纠正经司法或行政程序认定的反竞争行为","why":"须有规定的认定前提。","correct":true},{"id":"0","text":"公共非商业使用","why":"条文规定的方向之一。","correct":true},{"id":"2","text":"普通商业机会即可不受限制申请","why":"忽略半导体特别条件。","correct":false}]}],"role":"公共采购项目经理","scenario":"供应短缺时，企业拟使用他人专利。团队以“社会需要”为由准备立即生产，却未明确许可机关、范围、报酬或审查。","summary":"强制许可是受条件约束的制度安排。紧急情况可影响事先协商要求，但不等于所有要求都消失。","variation":{"labels":["一般商业使用","题定国家紧急情况"],"results":["检查事先协商努力及其它授权条件。","事先协商要求可按制度豁免，但通知、范围、报酬等不能一并略去。"]},"worked":"把条件分成协商、授权范围和保障三组。例外只作用于其规定覆盖的条件；企业不能以“紧急”替主管机关完成所有决定。"},{"id":"P08","title":"改进专利也可能需要别人的许可","case":"基础技术与改进方案","pages":"26–27","scope":"TRIPS 第 31(k)、31(l)、40 条：反竞争与依赖专利的不同条件","nodes":[{"label":"相互依赖","text":"后发专利不能实施而必须使用前专利时，需要核查依赖关系。","fact":"自己获得授权不直接产生他人许可。"},{"label":"改进门槛","text":"第 31(l) 条要求重要技术进步并具有重大经济意义，且有交叉许可等安排。","fact":"不只是“有一点改进”便足够。"},{"label":"竞争救济","text":"经规定程序认定反竞争行为时，第 31(k) 条可调整事先协商和主要供国内市场条件。","fact":"主观觉得贵不等于已认定反竞争。"}],"evidence":[{"label":"技术对照","text":"改进方案增加控制功能，但仍需采用基础专利覆盖的结构。"},{"label":"谈判记录","text":"许可方要价较高，暂无司法或行政反竞争认定。"}],"questions":[{"id":"P08-q1","stem":"公司已有改进专利，却使用了基础专利覆盖的方案。哪些说法正确？","options":[{"id":"1","text":"需对照两项权利的技术范围","why":"先确认实际依赖关系。","correct":true},{"id":"0","text":"仍可能需要基础专利许可","why":"自己的排他权不等于实施自由。","correct":true},{"id":"3","text":"有任何改进就能无偿实施所有基础技术","why":"遗漏许可及法定条件。","correct":false},{"id":"2","text":"后申请的专利自动消灭前专利","why":"无此自动规则。","correct":false}]},{"id":"P08-q2","stem":"企业援引第 31(l) 条处理依赖专利。哪些条件相关？","options":[{"id":"2","text":"只要第二项专利申请日较晚就足够","why":"时间不能替代技术和经济条件。","correct":false},{"id":"3","text":"无需证明实施时依赖基础专利","why":"依赖关系是该路径前提。","correct":false},{"id":"0","text":"重要技术进步且具有重大经济意义","why":"不能只主张略有变化。","correct":true},{"id":"1","text":"基础专利人应有按合理条件取得交叉许可的安排","why":"属于条文保障。","correct":true}]},{"id":"P08-q3","stem":"许可费较高，企业尚未获得反竞争认定。哪些判断稳妥？","options":[{"id":"0","text":"不能直接当作第 31(k) 条前提已满足","why":"需规定的司法或行政认定。","correct":true},{"id":"1","text":"可调查有关市场、行为及竞争影响","why":"为进一步分析提供依据。","correct":true},{"id":"2","text":"企业觉得不公平就可自行免除所有条件","why":"主观不满不产生该效果。","correct":false},{"id":"3","text":"所有收费许可都属于反竞争行为","why":"许可并非当然违法。","correct":false}]},{"id":"P08-q4","stem":"已有规定程序认定反竞争行为，拟适用第 31(k) 条。哪些说法成立？","options":[{"id":"2","text":"因此任何报酬和审查都自动消失","why":"调整范围不能扩张。","correct":false},{"id":"0","text":"可以不适用条文所列事先协商条件","why":"针对特定条件的调整。","correct":true},{"id":"1","text":"可不适用主要供应国内市场的所列条件","why":"不能与一般情形混同。","correct":true},{"id":"3","text":"纠正反竞争需要可影响报酬确定","why":"条文明确考虑该因素。","correct":true}]},{"id":"P08-q5","stem":"基础与改进专利双方准备谈判。哪些安排值得明确？","options":[{"id":"0","text":"双方许可的技术范围和实施行为","why":"避免许可覆盖不足。","correct":true},{"id":"3","text":"只用“双方合作愉快”替代全部许可范围","why":"无法明确实际授权。","correct":false},{"id":"1","text":"报酬、地域、期限及相关交叉许可","why":"需要可执行的具体条件。","correct":true},{"id":"2","text":"区分自愿协议与法定非自愿路径","why":"法律基础不同。","correct":true}]}],"role":"技术合作经理","scenario":"公司拥有改进专利，但实施时仍需使用他人的基础专利。团队另怀疑基础专利人的许可安排排斥竞争。","summary":"有改进专利不表示能绕开基础专利；依赖专利与反竞争救济属于不同路径，条件不能互相挪用。","variation":{"labels":["仅有改进专利证书","已有规定程序的反竞争认定"],"results":["继续核查基础权利与许可，不直接放行实施。","再分析第 31(k) 条相应条件调整，不能把调整扩大到全部条件。"]},"worked":"先确定实施需要什么权利，再区分自愿谈判、依赖专利与反竞争救济。每条路径分别列条件，别用一份授权证或一句“太贵”跳过判断。"},{"id":"P09","title":"没有药厂的市场如何获得药品","case":"药品生产与出口计划","pages":"28–30","scope":"TRIPS 第 31bis 条及附件；题目不替代完整申请指南","nodes":[{"label":"制度入口","text":"确认符合条件的进口成员与有关药品需求，依附件办理。","fact":"不是任何产品的任意出口豁免。"},{"label":"出口安排","text":"在制度必要范围内，出口成员不受第 31(f) 条相应义务限制。","fact":"豁免针对药品及规定安排。"},{"label":"报酬与地域","text":"出口成员支付规定报酬；符合条件时进口成员避免相同产品重复报酬。","fact":"机制不取消专利地域性及其它相关条件。"}],"evidence":[{"label":"供应需求","text":"进口成员符合题定机制资格，确认品种和需要数量。"},{"label":"生产方案","text":"拟由出口成员依制度授予许可，尚待完成附件要求。"}],"questions":[{"id":"P09-q1","stem":"出口药厂称第 31bis 条允许任何专利产品自由出口。哪些纠正正确？","options":[{"id":"3","text":"只要产品有专利就可以免许可出口","why":"专利本身不产生许可。","correct":false},{"id":"2","text":"所有国际买家自动是合格进口成员","why":"资格需核实。","correct":false},{"id":"1","text":"需要满足条文和附件条件","why":"目的合适仍不等于程序完成。","correct":true},{"id":"0","text":"机制针对规定药品及符合条件安排","why":"不是所有工业品的豁免。","correct":true}]},{"id":"P09-q2","stem":"合格进口成员缺乏相关制造能力，准备使用本机制。哪些资料需要明确？","options":[{"id":"1","text":"进口成员资格及相关能力情况","why":"不能只看商业合同。","correct":true},{"id":"2","text":"出口成员的生产许可安排","why":"两端制度需衔接。","correct":true},{"id":"0","text":"所需药品及数量等制度信息","why":"与通知和许可安排相关。","correct":true},{"id":"3","text":"只需买方付款收据","why":"不能代替机制条件。","correct":false}]},{"id":"P09-q3","stem":"依本机制出口时，哪些一般义务变化说法成立？","options":[{"id":"0","text":"第 31(f) 条在规定必要范围内不适用","why":"是有范围的例外。","correct":true},{"id":"1","text":"不表示第 31 条全部条件均被取消","why":"要逐项看保留规则。","correct":true},{"id":"3","text":"药厂取得一份许可即可无限量供应所有市场","why":"许可范围和制度条件仍在。","correct":false},{"id":"2","text":"所有专利从此成为全球统一权利","why":"地域性没有被取消。","correct":false}]},{"id":"P09-q4","stem":"出口成员已按本制度为相同产品支付规定报酬，进口成员也授许可。哪些说法正确？","options":[{"id":"2","text":"任何强制许可都不需要报酬","why":"机制不是全面免费。","correct":false},{"id":"1","text":"出口方报酬考虑进口成员的使用经济价值","why":"需对应条文安排。","correct":true},{"id":"3","text":"报酬只能看药厂自己希望支付多少","why":"需依法确定。","correct":false},{"id":"0","text":"规定情形下进口成员不再负担重复报酬义务","why":"避免对相同产品重复计算。","correct":true}]},{"id":"P09-q5","stem":"区域采购项目讨论第 31bis 条的特定区域安排。哪些核查适当？","options":[{"id":"1","text":"核对相关成员共同健康问题","why":"应符合条文所定情境。","correct":true},{"id":"3","text":"只要两个国家签采购合同便自动符合","why":"缺少制度前提。","correct":false},{"id":"0","text":"核对区域贸易安排及成员构成等条件","why":"并非任意邻国组合都适用。","correct":true},{"id":"2","text":"继续考虑专利地域性","why":"区域安排未取消这一点。","correct":true}]}],"role":"药品供应项目协调人","scenario":"某符合条件的进口成员缺乏相关制造能力，拟由出口成员的药厂按制度生产药品。团队担心一般国内供应条件阻碍出口。","summary":"第 31bis 条为符合条件的药品生产出口提供特别机制；资格、通知、许可范围和报酬仍需核查。","variation":{"labels":["一般工业产品出口","符合机制的药品生产出口"],"results":["不能直接套用药品专门机制。","检查进口资格、通知、数量和许可等完整安排。"]},"worked":"先确认特殊机制入口，再看豁免究竟改变哪项一般要求。报酬、通知、标识与防止转流等附件安排需按实际制度核查，不能把公共健康目的写成全面免条件。"},{"id":"P10","title":"药品获批与专利到期是一回事吗","case":"仿制药上市时间表","pages":"12–13","scope":"课件中国专利法第 76 条框架；专利链接不等于自动延长至 30 年","nodes":[{"label":"审批与专利","text":"上市审批与专利权利范围争议是不同问题。","fact":"审批通过不自动证明没有侵权。"},{"label":"中国机制例子","text":"第 76 条设置有关诉讼与行政裁决路径，审批决定与生效裁判可发生衔接。","fact":"应核对药品技术方案是否落入他人专利范围。"},{"label":"期限核对","text":"审批衔接、期限补偿与一般专利期限需分开。","fact":"课件的“20 到 30 年？”是讨论，不能作为自动规则。"}],"evidence":[{"label":"时间表","text":"专利申请、批准上市和计划投产日期分别记录。"},{"label":"风险备注","text":"有人把课件带问号的讨论改写成“每项药品专利必定延长十年”。"}],"questions":[{"id":"P10-q1","stem":"药品团队已获监管审批，声称无需再核查专利。哪些判断正确？","options":[{"id":"1","text":"仍应检查相关有效专利","why":"题定批准不证明实施自由。","correct":true},{"id":"3","text":"获得专利就自动获得药品上市许可","why":"反向推论同样错误。","correct":false},{"id":"2","text":"监管审批自动宣告所有相关专利无效","why":"没有这种效果。","correct":false},{"id":"0","text":"审批与专利范围是不同问题","why":"不能用批准替代侵权分析。","correct":true}]},{"id":"P10-q2","stem":"依课件所引中国第 76 条，哪些路径相关？","options":[{"id":"2","text":"任何消费者投诉都自动延长全部专利","why":"与机制不符。","correct":false},{"id":"3","text":"只需企业内部决定便可约束审批机关","why":"内部意见不等于有效裁判或制度决定。","correct":false},{"id":"0","text":"就有关药品技术方案是否落入专利范围提起诉讼","why":"是该机制方向之一。","correct":true},{"id":"1","text":"依规定请求相关专利主管部门行政裁决","why":"需满足具体制度条件。","correct":true}]},{"id":"P10-q3","stem":"报告写“专利链接把二十年固定改成三十年”。哪些纠正合理？","options":[{"id":"1","text":"期限补偿等制度须另有依据并核查条件","why":"不同机制不能混用。","correct":true},{"id":"0","text":"链接机制本身不等于统一法定期限变更","why":"不能把政策评价当计算公式。","correct":true},{"id":"3","text":"课件带问号的讨论应与规则分开","why":"保留信息性质。","correct":true},{"id":"2","text":"只要审批慢就当然增加十年","why":"无此自动规则。","correct":false}]},{"id":"P10-q4","stem":"某药品争议进入裁判程序。项目经理应区分哪些时间？","options":[{"id":"2","text":"只保留产品广告发布日期即可","why":"与主要程序不匹配。","correct":false},{"id":"1","text":"药品申请、审批及相关争议节点","why":"关系到程序衔接。","correct":true},{"id":"0","text":"专利申请及有效期","why":"关系到权利状态。","correct":true},{"id":"3","text":"所有日期可合并成一个授权日起点","why":"会混淆对象。","correct":false}]},{"id":"P10-q5","stem":"跨国药企把中国机制直接套到所有市场。哪些做法更合理？","options":[{"id":"0","text":"逐市场核查审批与专利衔接制度","why":"国家制度可能不同。","correct":true},{"id":"1","text":"分别审查专利期限及可能补偿","why":"不能借用另一市场结论。","correct":true},{"id":"2","text":"区分尚待审查、已裁判与已生效状态","why":"程序状态影响判断。","correct":true},{"id":"3","text":"把起诉本身当作侵权已被认定","why":"诉讼主张不是终局结论。","correct":false}]}],"role":"药品项目经理","scenario":"团队同时管理仿制药审批和相关专利争议。计划表把审评等待直接写成专利自动延长十年。","summary":"药品审批判断与专利争议不同；两条程序可以衔接，但衔接本身不直接改写专利法定期限。","variation":{"labels":["只有上市审批已通过","已有生效专利争议裁判"],"results":["仍需核查有关专利和其它上市条件。","按具体机制分析对审批决定的影响，不直接重算一般专利期限。"]},"worked":"先画两条时间轴：专利申请及有效期、药品申请及审批。争议程序的连接点另列，不把等待天数随意加到专利期限上。"},{"id":"P11","title":"芯片买来后才收到侵权通知","case":"芯片库存的去向","pages":"32–35","scope":"TRIPS 第 35–38 条集成电路布图设计；特别分析购入时知情与通知后库存","nodes":[{"label":"行为范围","text":"商业性进口、销售或分销相关受保护布图、芯片及含有它的产品属于分析范围。","fact":"整机销售也可能涉及其中芯片。"},{"label":"购入时状态","text":"购入时不知且无合理理由知道非法复制，条约规定相应处理。","fact":"不能把收到通知后的认识倒推为购入时已知。"},{"label":"通知后库存","text":"充分通知后，规定库存及已订货仍可处理，但须付相当于合理许可费的款项。","fact":"不支持未来无限量新增采购。"}],"evidence":[{"label":"采购记录","text":"采购时没有侵权信息或合理可疑线索，保留尽调资料。"},{"label":"通知与库存","text":"充分通知已收到；现货 200 件，另有通知前订单 100 件。"}],"questions":[{"id":"P11-q1","stem":"采购时不知且无合理理由知道非法复制布图。哪些事实重要？","options":[{"id":"1","text":"采购资料与所获信息","why":"帮助证明题定状态。","correct":true},{"id":"0","text":"采购当时的知情和合理注意情况","why":"这是第 37 条关键时间点。","correct":true},{"id":"2","text":"之后收到通知就证明当初必然知道","why":"不能倒推事实。","correct":false},{"id":"3","text":"只要口头声称善意就无需核查任何证据","why":"要有事实支持。","correct":false}]},{"id":"P11-q2","stem":"收到充分通知后，仓库有原库存和此前已订货。哪些判断正确？","options":[{"id":"3","text":"原先善意意味着通知后无需任何处理","why":"忽略阶段变化。","correct":false},{"id":"2","text":"通知后任何新增采购都自动适用同一安排","why":"不能扩张库存规则。","correct":false},{"id":"0","text":"条约对这些产品继续处理有特别安排","why":"范围限于规定库存和已订货。","correct":true},{"id":"1","text":"需支付相当于合理许可费的款项","why":"不是永久免费豁免。","correct":true}]},{"id":"P11-q3","stem":"企业把含非法复制布图的芯片装入整机销售。哪些核查相关？","options":[{"id":"0","text":"整机是否仍含该非法复制布图","why":"条文也涉及含相关芯片的产品。","correct":true},{"id":"2","text":"装入外壳就自动切断全部布图问题","why":"物理包装不产生这种效果。","correct":false},{"id":"1","text":"销售的商业性质与授权状态","why":"对应保护范围。","correct":true},{"id":"3","text":"布图保护只涉及芯片设计者之间的合同","why":"保护不局限于合同。","correct":false}]},{"id":"P11-q4","stem":"团队将布图设计期限一律按普通专利二十年计算。哪些纠正正确？","options":[{"id":"0","text":"布图设计有独立期限条款","why":"不能直接套普通发明专利。","correct":true},{"id":"2","text":"所有知识产权都共享同一保护期","why":"对象不同。","correct":false},{"id":"3","text":"还需关注可规定创作后十五年届满的安排","why":"条文允许这一上限机制。","correct":true},{"id":"1","text":"需区分登记制度与首次商业利用等起点","why":"第 38 条有具体安排。","correct":true}]},{"id":"P11-q5","stem":"采购收到通知后准备下新订单。哪些操作更稳妥？","options":[{"id":"0","text":"把新订单与旧库存分开","why":"不能借用旧库存特别规则。","correct":true},{"id":"2","text":"保存通知送达与订单时间","why":"时间直接影响分析。","correct":true},{"id":"1","text":"核查授权并与权利方处理许可事项","why":"需要新的使用依据。","correct":true},{"id":"3","text":"把新订单倒填成旧订单以获取豁免","why":"不能制造虚假时间事实。","correct":false}]}],"role":"电子企业采购经理","scenario":"采购时没有知道或合理理由知道芯片含非法复制布图。货到后收到充分通知，仓库还有现货和通知前已订货。","summary":"先看采购时的知情状态，再区分通知前库存、已订货与新的采购；布图设计不是普通发明专利期限的简单翻版。","variation":{"labels":["分析采购当时","分析收到充分通知之后"],"results":["看当时是否知道或有合理理由知道，不能仅靠事后通知重写事实。","对现有库存和此前已订货核查合理使用费等安排，新增订单另行分析。"]},"worked":"先画采购—通知—后续处理时间线。第 37 条的善意取得与通知后库存处理有各自条件，不能概括成“善意者永久免费卖”。"},{"id":"S01","title":"哪些资料能算商业秘密","case":"茶饮店的资料盘点","pages":"2–5、16、26","scope":"TRIPS 第 39.2 条：秘密性、因保密具有价值、合理措施","nodes":[{"label":"秘密性","text":"不是相关领域普遍知晓或容易取得的整体信息或精确组合。","fact":"公开原料不一定说明精确比例组合也公开。"},{"label":"商业价值","text":"要看信息因其秘密状态而具有的商业价值。","fact":"公开菜单即使有价值，也不因此成为秘密。"},{"label":"合理措施","text":"控制人应按具体情境采取合理步骤维持秘密。","fact":"访问权限、保密约定及操作记录可提供线索。"}],"evidence":[{"label":"资料甲","text":"官网菜单可自由下载，老板在公司副本上加了秘密水印。"},{"label":"资料乙","text":"精确配方限制两人访问，有保密约定和访问记录，保密可保持成本优势。"}],"questions":[{"id":"S01-q1","stem":"公开菜单被公司盖上商业秘密章。哪些判断正确？","options":[{"id":"2","text":"老板主观认定足以构成商业秘密","why":"主观标签不是全部标准。","correct":false},{"id":"0","text":"水印不能替代实际秘密性","why":"公众可自由取得是相反事实。","correct":true},{"id":"1","text":"资料有商业价值也不自动满足全部条件","why":"三个条件需分别判断。","correct":true},{"id":"3","text":"任何餐饮资料都无法成为商业秘密","why":"精确配方等仍可能符合。","correct":false}]},{"id":"S01-q2","stem":"未公开配方因保密保持成本优势，且限制访问。哪些事实支持保护条件？","options":[{"id":"1","text":"保密带来的竞争价值","why":"对应因秘密而有价值。","correct":true},{"id":"0","text":"相关行业不能轻易获得精确配方","why":"对应秘密性。","correct":true},{"id":"3","text":"只有配方申请了专利才可能保护","why":"商业秘密不以专利申请为前提。","correct":false},{"id":"2","text":"限制访问及保密措施","why":"对应合理措施。","correct":true}]},{"id":"S01-q3","stem":"原料名称公开，但精确组合与比例不易取得。哪些判断适当？","options":[{"id":"2","text":"每个成分已知便证明比例必然公开","why":"推论不成立。","correct":false},{"id":"3","text":"组合复杂就无需采取任何措施","why":"措施仍是独立条件。","correct":false},{"id":"1","text":"不能仅凭各成分已知否定全部保护可能","why":"整体与组成部分需分开。","correct":true},{"id":"0","text":"仍应分析精确组合的秘密性","why":"条文考虑组合和排列整体。","correct":true}]},{"id":"S01-q4","stem":"重要客户数据放在全员无约束共享盘。哪些改进方向合理？","options":[{"id":"2","text":"改名“最高机密”即可替代所有操作","why":"标签不等于合理措施。","correct":false},{"id":"3","text":"设置措施后历史上公开的内容自动变秘密","why":"实际秘密状态仍需判断。","correct":false},{"id":"0","text":"按业务需要限制权限并保留记录","why":"有助建立实际保密措施。","correct":true},{"id":"1","text":"明确可使用范围与离职交接","why":"措施应对应真实流程。","correct":true}]},{"id":"S01-q5","stem":"新企业核查研发资料，哪些分析顺序适当？","options":[{"id":"3","text":"只要项目投入很大就直接判定员工侵害","why":"成本与行为都不能省略审查。","correct":false},{"id":"2","text":"记录哪些事实仍不足以证明","why":"结论应受证据限制。","correct":true},{"id":"0","text":"逐项确认秘密性、价值与合理措施","why":"先判断保护基础。","correct":true},{"id":"1","text":"再调查获取、使用或披露方式","why":"保护条件不等于侵害行为。","correct":true}]}],"role":"企业信息管理员","scenario":"公司有官网公开菜单、只供两名研发人员访问的配方，以及没有权限限制的内部资料盘。老板想把全部内容统一盖“商业秘密”章。","summary":"先看信息是否真正秘密、是否因秘密有商业价值、是否采取合理保密措施；文件名和盖章不能替代三项条件。","variation":{"labels":["官网公开菜单","未公开配方及合理访问控制"],"results":["秘密水印不能让公众已易取得的信息重新变成秘密。","题定事实支持逐项分析三条件，但具体侵害还需另查行为。"]},"worked":"把资料分别放进三条件图。公开菜单卡在秘密性；配方则有秘密、价值和措施的对应事实。符合保护条件与某人已经侵害，是下一步不同问题。"},{"id":"S02","title":"新员工带来的资料能直接用吗","case":"入职电脑里的旧图纸","pages":"3、5、82–83","scope":"TRIPS 第 39.2 条及脚注 10；获取、披露、使用和第三方知情","nodes":[{"label":"行为链","text":"获取、披露、使用是不同环节。","fact":"接收文件后投入生产属于新的行为。"},{"label":"诚实商业惯例","text":"TRIPS 脚注涉及违约、违反保密义务、诱导违反等。","fact":"员工参与过研发不直接拥有对外处分权。"},{"label":"第三方状态","text":"知道或因重大过失不知不当取得等事实，会影响有关分析。","fact":"保密标记和具体通知都是需调查的线索。"}],"evidence":[{"label":"文件信息","text":"图纸署名前雇主，带保密标记，未附对外授权。"},{"label":"员工说明","text":"员工只提供自己参与项目的证明，不能提供携出使用许可。"}],"questions":[{"id":"S02-q1","stem":"新员工说自己参与制作图纸，便可带到新公司。哪些判断合理？","options":[{"id":"3","text":"新公司没去旧公司现场就完全无须调查","why":"后续接收使用也需分析。","correct":false},{"id":"1","text":"需检查前雇主授权和信息保护条件","why":"不能只凭身份下结论。","correct":true},{"id":"0","text":"参与制作不直接证明可对外使用","why":"权属与保密义务需核查。","correct":true},{"id":"2","text":"员工记得文件内容就可以随意传播","why":"记忆形式不直接解决义务问题。","correct":false}]},{"id":"S02-q2","stem":"新公司收到具体侵权通知并发现保密标记。哪些行动适当？","options":[{"id":"2","text":"立刻把文件换名以消除问题","why":"换名不改变来源和权限。","correct":false},{"id":"3","text":"只问员工愿不愿承担责任即可继续用","why":"个人承诺不能替代合法授权。","correct":false},{"id":"0","text":"核实来源和授权链条","why":"知情线索要求实质核查。","correct":true},{"id":"1","text":"保存合法取得的通知和文件记录","why":"便于调查而非销毁事实。","correct":true}]},{"id":"S02-q3","stem":"企业诱导合作方违反其保密约定交出资料。按 TRIPS 脚注框架，哪些说法正确？","options":[{"id":"3","text":"支付了资料费便证明来源正当","why":"付费不能洗去不当取得。","correct":false},{"id":"1","text":"获取与后续使用应分别记录","why":"行为链可能涉及多个环节。","correct":true},{"id":"0","text":"诱导违反义务属于相关不当方式","why":"需要结合保护信息和具体事实。","correct":true},{"id":"2","text":"有合作关系就可忽略对方全部既有义务","why":"合作不产生该豁免。","correct":false}]},{"id":"S02-q4","stem":"竞争者独立研发出相同信息，没有接触秘密文件。哪些区分有必要？","options":[{"id":"1","text":"可用研发记录说明独立过程","why":"证据对应关键事实。","correct":true},{"id":"2","text":"商业秘密意味着别人永远不能独立发现","why":"保护不等于垄断所有相同信息。","correct":false},{"id":"3","text":"只比较最终结果即可证明窃取","why":"忽略行为方式。","correct":false},{"id":"0","text":"相同结果不自动证明不当取得","why":"要核查真实研发来源。","correct":true}]},{"id":"S02-q5","stem":"企业要处理一份客户名单泄露线索。哪些问题应同时调查？","options":[{"id":"1","text":"资料由谁以何方式传出和使用","why":"建立行为链。","correct":true},{"id":"0","text":"名单是否符合保护条件","why":"不是所有名单都自动是秘密。","correct":true},{"id":"2","text":"接收者知道或应调查的具体线索","why":"第三方状态很重要。","correct":true},{"id":"3","text":"先宣布所有接收者都构成刑事犯罪","why":"民事和刑事条件不能跳过。","correct":false}]}],"role":"研发部门负责人","scenario":"新员工带来前雇主标有保密要求的设计文件，说“我参与过项目，可以继续用”。你还收到要求停止使用的正式通知。","summary":"先确认信息符合保护条件，再追查来源、权限、行为和知情状态；没有亲自窃取也不代表后续使用无需核查。","variation":{"labels":["来源与许可尚不清楚","已有充分合法授权"],"results":["先隔离核查，保留合法证据；不宜凭口头说明直接投入生产。","按真实授权范围核对使用，但仍不要越过用途和对象限制。"]},"worked":"沿前雇主—员工—新公司画行为链。参与研发不等于可带走；新公司收到明显线索后，应核查权属和许可，而不是只问自己是否亲自偷取。"},{"id":"S03","title":"试验数据、数据独占与专利","case":"药品申请材料的三条线","pages":"4、27–32","scope":"TRIPS 第 39.3 条及课件比较例子；各地数据制度与期限须另查","nodes":[{"label":"条约数据保护","text":"第 39.3 条针对规定情形的未公开、付出相当努力产生的试验或其它数据。","fact":"需核实新化学实体及监管要求等条件。"},{"label":"不公平使用与披露","text":"保护免于不公平商业使用及披露，并有条文所述公共保护等安排。","fact":"不是监管机关收到的任何信息都按同一条件处理。"},{"label":"制度差别","text":"具体数据独占、申请限制或依赖资料限制依当地制度。","fact":"不能把一种制度简单写成全球统一的五年禁申请。"}],"evidence":[{"label":"材料清单","text":"涉及新化学实体，申报所需数据未公开且产生耗费相当努力。"},{"label":"项目计划","text":"把专利到期日、监管数据事项和上市申请日混在同一栏。"}],"questions":[{"id":"S03-q1","stem":"仿制团队认为原研专利期满即可直接复制未公开申报资料。哪些纠正正确？","options":[{"id":"0","text":"专利与数据保护是不同制度","why":"期限不能互相替代。","correct":true},{"id":"1","text":"仍需核查资料取得及依赖的依据","why":"不能直接推定可用。","correct":true},{"id":"3","text":"数据永远只能由原研企业独占，无任何条件","why":"同样忽略制度差异。","correct":false},{"id":"2","text":"专利期满便消灭一切监管要求","why":"超出专利期限的效果。","correct":false}]},{"id":"S03-q2","stem":"监管要求提交新化学实体相关未公开试验资料，产生投入相当努力。哪些条件相关？","options":[{"id":"2","text":"只要材料页数多便自动符合全部要件","why":"页数不能替代各项事实。","correct":false},{"id":"1","text":"有关产品和监管提交要求","why":"并非任意公司资料都属于同一条款。","correct":true},{"id":"3","text":"已经公开的数据仍无需分析秘密状态","why":"公开状态会影响适用。","correct":false},{"id":"0","text":"未公开及相当努力","why":"第 39.3 条有这些条件。","correct":true}]},{"id":"S03-q3","stem":"报告称 TRIPS 明文要求全球统一五年数据独占。哪些纠正有依据？","options":[{"id":"3","text":"不同法域的申请、依赖与批准限制需分别核查","why":"限制环节可能不同。","correct":true},{"id":"0","text":"第 39.3 条没有这样统一规定固定五年独占","why":"不能把本地制度写成条约统一要求。","correct":true},{"id":"2","text":"课件列举一个国家就证明全球期限相同","why":"例子不代表统一规则。","correct":false},{"id":"1","text":"应区分不公平使用保护与具体独占制度","why":"二者并非相同术语。","correct":true}]},{"id":"S03-q4","stem":"有人把任何数据披露都视为条约绝对禁止。哪些判断正确？","options":[{"id":"3","text":"存在公共保护理由就自动可以任意商业复制","why":"例外不能无限扩张。","correct":false},{"id":"2","text":"只要企业不愿意就能排除全部公共保护安排","why":"不是单方决定。","correct":false},{"id":"0","text":"条文有保护公众等相关安排","why":"不能删除所列限定。","correct":true},{"id":"1","text":"还要考虑防止不公平商业使用的措施","why":"披露问题需看完整条文。","correct":true}]},{"id":"S03-q5","stem":"跨国药企比较课件中的新加坡和台湾地区例子。哪些做法合理？","options":[{"id":"2","text":"区分法律条文和印度报告中的政策建议","why":"来源性质不同。","correct":true},{"id":"0","text":"分别记录制度对象、起点及限制环节","why":"便于避免混用。","correct":true},{"id":"1","text":"核查业务发生时的适用版本","why":"课件节选可能不是完整现行制度。","correct":true},{"id":"3","text":"把“不得依赖资料”一律改写为“任何申请都不得提交”","why":"会扩大限制含义。","correct":false}]}],"role":"药品注册协调人","scenario":"原研企业提交未公开且投入巨大努力获得的试验资料。仿制团队认为专利到期就可以直接取得所有申报材料。","summary":"专利、监管数据保密和特定制度的数据独占是不同问题；一个期限结束不自动回答另外两项。","variation":{"labels":["仅知道专利已经到期","已分别查明三种制度"],"results":["仍需检查监管数据制度和申请依据，不能直接取得对方资料。","可建立分开的计划表，按各自起点和条件安排。"]},"worked":"画三条线：专利权、资料保密、特定独占安排。先说明适用条件，再讨论能否依赖资料、何时申请和何时获批，避免把不同限制写成一句话。"},{"id":"S04","title":"保密协议会不会挡住竞争","case":"维修市场与药品和解","pages":"41–45","scope":"课件竞争案例的分析方法；线索、承诺、裁判结论须分开","nodes":[{"label":"市场与依赖","text":"是否有替代来源、供应者地位和下游竞争都重要。","fact":"无法替代的零件与普通可替换零件不同。"},{"label":"行为与效果","text":"拒绝供应、延迟进入、反向付款等需按具体事实分析。","fact":"存在协议不直接证明合法或违法。"},{"label":"程序状态","text":"调查、承诺和裁判有不同含义。","fact":"接受供货承诺不等于每个争议事实都已有定罪结论。"}],"evidence":[{"label":"维修投标","text":"第三方维修商无法取得某型号必要零件，暂未发现替代供应。"},{"label":"协议线索","text":"另一药品项目拟以付款换取竞争者延迟进入市场，费用理由待核实。"}],"questions":[{"id":"S04-q1","stem":"零件唯一供应方拒绝向第三方维修商供货。哪些事实值得调查？","options":[{"id":"3","text":"只要拒供就必然已经违法","why":"需具体条件和分析。","correct":false},{"id":"1","text":"对下游维修竞争的实际影响","why":"不能只看供货方的主张。","correct":true},{"id":"0","text":"是否存在可替代产品和供应者","why":"涉及市场依赖。","correct":true},{"id":"2","text":"一说保密就必然排除竞争法问题","why":"不同制度可交叉。","correct":false}]},{"id":"S04-q2","stem":"药企向竞争者付款换其推迟上市。哪些问题相关？","options":[{"id":"3","text":"所有和解付款都自动违法","why":"同样省略具体分析。","correct":false},{"id":"0","text":"付款与推迟进入之间的关系","why":"有助分析安排实质。","correct":true},{"id":"2","text":"标注和解就自动不受竞争审查","why":"和解形式不是绝对豁免。","correct":false},{"id":"1","text":"费用理由、市场影响及适用规则","why":"不能只看协议标题。","correct":true}]},{"id":"S04-q3","stem":"公司想通过保密条款隐藏可能限制竞争的协议。哪些纠正合理？","options":[{"id":"3","text":"竞争问题只存在于公开签订的合同","why":"不公开并不改变行为性质。","correct":false},{"id":"1","text":"应区分真实秘密保护与限制竞争安排","why":"需要分析内容和效果。","correct":true},{"id":"0","text":"保密约定不等于行为获得合法性","why":"合同标签不能代替规则审查。","correct":true},{"id":"2","text":"双方自愿就能排除全部公共监管","why":"私人同意并非万能。","correct":false}]},{"id":"S04-q4","stem":"监管机关接受供应商按条件供货的承诺。哪些报道表述准确？","options":[{"id":"1","text":"不把它随意改写为刑事定罪","why":"不同程序结果不能混用。","correct":true},{"id":"2","text":"直接称所有高管已被法院判罪","why":"没有题定依据。","correct":false},{"id":"3","text":"没有罚款就证明从来无竞争风险","why":"承诺不支持如此推论。","correct":false},{"id":"0","text":"说明是承诺及具体供货条件","why":"保留程序性质。","correct":true}]},{"id":"S04-q5","stem":"采购合同含“不反向工程”条款。哪些审查方向适当？","options":[{"id":"3","text":"所有反向工程在任何国家都绝对合法且不可约定","why":"法域和合同差异不能省略。","correct":false},{"id":"2","text":"核对取得产品的条件及用途","why":"合同事实影响判断。","correct":true},{"id":"0","text":"结合适用法和实际条款分析约束","why":"不能仅凭名称下结论。","correct":true},{"id":"1","text":"考虑保密利益与市场竞争影响","why":"需要业务情境。","correct":true}]}],"role":"商业合作审查经理","scenario":"零部件供应商只向自己的维修部门供货，第三方维修商无法取得替代零件。另一个项目中，药企付费换取竞品延迟上市。","summary":"保密标签不自动解决竞争问题。先看市场、行为和影响，再区分真实保密需要、合同安排与限制竞争风险。","variation":{"labels":["存在多个可替代零件供应源","零件无可替代且供应受限"],"results":["竞争依赖程度的事实改变，需要重新分析市场影响。","竞争风险更值得调查，但仍需法律与事实判断。"]},"worked":"先画上游供应与下游维修关系，再看行为对竞争的具体影响。保密需要和公平供应条件可以同时讨论，不能用一句“商业秘密”结束分析。"},{"id":"S05","title":"保密不能写成永远不准跳槽","case":"研发员工的离职安排","pages":"17–20、46–49、92–95","scope":"保密与竞业的区别；德国 HGB 第 74、74a 条的课件例子","nodes":[{"label":"保密义务","text":"聚焦特定信息及禁止的不当披露或使用。","fact":"不能把员工所有技能都简单写成企业秘密。"},{"label":"竞业限制","text":"直接限制职业活动，适用法域差异明显。","fact":"存在 NDA 不等于同行就业必然违法。"},{"label":"德国例子","text":"课件所引适用对象下，最多离职后两年，补偿至少最近合同报酬一半，还要避免不合理妨碍。","fact":"满足期限不代表其它条件自动满足。"}],"evidence":[{"label":"条款甲","text":"禁止披露列明的保密研发资料，约定归还文件。"},{"label":"条款乙","text":"终身不得在全球任何同行任职，未承诺补偿。"}],"questions":[{"id":"S05-q1","stem":"企业把保密协议解释为员工不得在任何同行就业。哪些纠正正确？","options":[{"id":"0","text":"保密与竞业限制需要分别分析","why":"限制对象和制度不同。","correct":true},{"id":"2","text":"只要员工知道业务就全部终身禁业","why":"范围和依据不足。","correct":false},{"id":"1","text":"要辨认具体保密信息与实际行为","why":"跳槽本身不证明泄密。","correct":true},{"id":"3","text":"有 NDA 就无需看当地就业规则","why":"法域规则仍相关。","correct":false}]},{"id":"S05-q2","stem":"题定员工适用课件所引德国规则，竞业期限写四年。哪些判断成立？","options":[{"id":"0","text":"超过所述离职后两年限制","why":"期限需按该框架核查。","correct":true},{"id":"3","text":"德国数值自动适用于所有国家员工","why":"法域不能混用。","correct":false},{"id":"2","text":"四年只要老板同意便当然有效","why":"单方意愿不足。","correct":false},{"id":"1","text":"还要核查补偿和合理保护利益","why":"期限并非唯一条件。","correct":true}]},{"id":"S05-q3","stem":"同样适用题定德国规则，雇主不承诺补偿。哪些分析有依据？","options":[{"id":"2","text":"保密信息重要就可无条件免除补偿","why":"不符合题定框架。","correct":false},{"id":"0","text":"应核查至少最近合同报酬一半的补偿要求","why":"这是本关明确条件。","correct":true},{"id":"1","text":"不能只因为员工签字就省略法定要求","why":"同意不代替条件。","correct":true},{"id":"3","text":"补偿足够便自动允许任何地域和业务限制","why":"合理范围仍需检查。","correct":false}]},{"id":"S05-q4","stem":"竞争企业约定互不招聘对方员工。哪些问题值得审查？","options":[{"id":"0","text":"企业间限制人才竞争的影响","why":"可能涉及竞争法方向。","correct":true},{"id":"3","text":"没有窃取文件就排除所有竞争风险","why":"不挖角安排是另一问题。","correct":false},{"id":"1","text":"与单个员工的保密义务区分","why":"协议主体和行为不同。","correct":true},{"id":"2","text":"双方方便管理就必然不存在竞争问题","why":"方便不是充分依据。","correct":false}]},{"id":"S05-q5","stem":"离职员工掌握一般经验，同时持有未归还的秘密图纸。哪些处理合理？","options":[{"id":"2","text":"根据有关法域分析竞业条款","why":"不能把德国例子直接搬到别处。","correct":true},{"id":"3","text":"以“员工有经验”为由证明所有未来工作都泄密","why":"结论超出事实。","correct":false},{"id":"1","text":"检查图纸归还及后续使用义务","why":"涉及具体资料管理。","correct":true},{"id":"0","text":"区分一般技能与特定秘密资料","why":"不能将两者打包独占。","correct":true}]}],"role":"人力与研发协调人","scenario":"企业准备要求研发员工终身不得进入同行，又未安排补偿。另一份协议只禁止泄露真实保密技术。","summary":"限制泄密与限制去哪里工作不是同一件事。竞业限制要看法域、范围、期限、保护利益与补偿。","variation":{"labels":["限制真实秘密的不当披露","全面限制未来职业活动"],"results":["核查信息、义务、行为及范围。","需按有关法域审查竞业限制，不能只援引保密需要。"]},"worked":"先把两个条款拆开。德国例子的期限和补偿是明确检查项，合理范围同样重要；其它法域不能直接复制这些数值。"},{"id":"S06","title":"跨境技术合作多了哪些检查","case":"日本与韩国的技术文件","pages":"53–68","scope":"按课件列示的日本、韩国历史条文作比较；不以旧罚则作为现行处罚表","nodes":[{"label":"行为与目的","text":"课件日本条文分别涉及获取、复制、使用、披露及不正利益或损害目的等。","fact":"有文件传输记录不等于已证明全部犯罪要件。"},{"label":"境外因素","text":"课件日、韩条文对境外使用和知情等作特别分析。","fact":"不能仅看员工国籍就替代行为与目的。"},{"label":"指定技术","text":"课件韩国制度对符合条件的指定核心技术出口另有审批安排。","fact":"题定指定、资助和出口事实要分别核实。"}],"evidence":[{"label":"日本记录","text":"员工曾获内部访问权，现被发现复制文件；目的和权限边界尚在调查。"},{"label":"韩国资料","text":"本题明确技术已按所引制度指定，并由政府研发资助，拟向境外出口。"}],"questions":[{"id":"S06-q1","stem":"依课件日本条文，员工内部可访问资料，却擅自复制。哪些调查必要？","options":[{"id":"2","text":"有访问账户就自动可带到任何公司","why":"权限有范围。","correct":false},{"id":"0","text":"复制是否超出权限或违反管理义务","why":"内部接触不等于任意利用。","correct":true},{"id":"1","text":"是否具备条文要求的目的等主观条件","why":"不能只凭动作认定全部责任。","correct":true},{"id":"3","text":"发现复制即证明所有刑事要件全部成立","why":"仍需其它事实。","correct":false}]},{"id":"S06-q2","stem":"境外接收方知道资料拟在境外使用。比较课件相关规则时，哪些因素相关？","options":[{"id":"2","text":"境外使用永远不可能被原地制度涉及","why":"课件正讨论境外关联。","correct":false},{"id":"3","text":"外籍身份本身足以证明经济间谍行为","why":"身份不替代行为要件。","correct":false},{"id":"0","text":"行为发生和使用地点","why":"跨境条文可能关注不同地点。","correct":true},{"id":"1","text":"目的、知情与资料属性","why":"不能只看国籍。","correct":true}]},{"id":"S06-q3","stem":"按题定韩国课件框架，技术已被指定为核心技术且政府资助研发，拟出口。哪些处理适当？","options":[{"id":"0","text":"核查有关出口批准安排","why":"题定事实触及特别制度。","correct":true},{"id":"1","text":"区分其与普通商业秘密许可","why":"两条路径可能并行。","correct":true},{"id":"2","text":"得到交易对手同意即可免除主管程序","why":"商业同意不替代批准。","correct":false},{"id":"3","text":"公司自称核心就等于依法指定","why":"本题明确指定，现实中须有依据。","correct":false}]},{"id":"S06-q4","stem":"报告准备照抄课件中的旧案件数量与刑罚上限作现行决策。哪些纠正合理？","options":[{"id":"1","text":"现行业务需要另查当时有效条文","why":"旧条文不是自动最新。","correct":true},{"id":"0","text":"旧统计应标明时期，不当作现在的概率","why":"资料时点决定解释范围。","correct":true},{"id":"2","text":"旧起诉率可以直接预测自己案件结果","why":"总体数据不能代替个案。","correct":false},{"id":"3","text":"核心学习应保留构成条件和制度区别","why":"历史数字无需作为通关重点。","correct":true}]},{"id":"S06-q5","stem":"合资项目要交换两国技术资料。哪些清单有用？","options":[{"id":"1","text":"是否涉及指定技术及出口程序","why":"特定制度需另查。","correct":true},{"id":"0","text":"资料是否秘密、权属及授权范围","why":"一般保护的基础。","correct":true},{"id":"2","text":"实际接收、使用地点和用途","why":"跨境事实需要明确。","correct":true},{"id":"3","text":"只查合作方国籍便可完成全部审查","why":"遗漏多数关键条件。","correct":false}]}],"role":"跨境研发合作经理","scenario":"日本团队发现员工复制受管控技术；韩国合作方又准备向境外输出题定已被指定且获得政府研发资助的核心技术。","summary":"跨境不只多一个地点。要区分一般秘密、相关主观目的、境外使用，以及另有指定和审批条件的核心技术制度。","variation":{"labels":["普通技术资料","题定已指定且符合资助条件"],"results":["先分析一般秘密和行为条件，不能自动称为国家核心技术。","进入课件特别出口审批路径，仍要核查程序与实际适用版本。"]},"worked":"把普通秘密分析和特别技术管制分成两条线。国内访问许可不等于境外转移许可；刑事认定还需逐项证明，旧刑罚数字不作为当前结论。"},{"id":"S07","title":"普通秘密与核心技术怎么分","case":"半导体合作的资料室","pages":"71–81","scope":"课件台湾地区营业秘密法及 2022 年国家安全法框架；题目以给定版本和指定事实为准","nodes":[{"label":"普通营业秘密","text":"先核查秘密定义、相关行为及责任条件。","fact":"研发成本高不能替代全部条件。"},{"label":"核心关键技术","text":"课件特别制度要求规定的技术条件及公告生效等安排。","fact":"“核心”标签不能代替指定依据。"},{"label":"调查保密","text":"受命令人对调查内容的使用和披露有限制，课件条文另有先前已取得等限定。","fact":"用于调查和用于业务培训不同。"}],"evidence":[{"label":"技术分类","text":"A 是普通未公开工艺，B 在本题中已依法公告为核心关键技术。"},{"label":"命令内容","text":"相关人员受到侦查保密令约束，拟向不受该令约束的培训人员披露调查内容。"}],"questions":[{"id":"S07-q1","stem":"公司把研发费最高的项目自动归为法定核心关键技术。哪些纠正适当？","options":[{"id":"3","text":"价格昂贵便自动证明刑事责任","why":"属性和责任要件不同。","correct":false},{"id":"0","text":"需核查法定条件与公告依据","why":"投入额不是指定本身。","correct":true},{"id":"2","text":"公司单方命名即可完成法定指定","why":"不符合本关框架。","correct":false},{"id":"1","text":"普通秘密仍有自己的保护分析","why":"未进入特别制度不等于无保护。","correct":true}]},{"id":"S07-q2","stem":"按课件特别框架分析已依法指定技术的外流。哪些事实仍需审查？","options":[{"id":"0","text":"获取、复制、使用或披露行为","why":"不能只看技术名称。","correct":true},{"id":"3","text":"所有接触者都自动有罪","why":"需分别分析。","correct":false},{"id":"2","text":"一有指定就无需证明任何行为","why":"指定不替代责任条件。","correct":false},{"id":"1","text":"相应主体、目的和地区联系","why":"须符合具体条文。","correct":true}]},{"id":"S07-q3","stem":"受侦查保密令约束者想把调查材料用于无关业务培训。哪些判断正确？","options":[{"id":"1","text":"向不受令约束者披露也是独立问题","why":"对象范围同样重要。","correct":true},{"id":"2","text":"是公司内部培训就当然不受限制","why":"命令范围不按内部外部简单划分。","correct":false},{"id":"3","text":"没有公开上网就不可能违反披露限制","why":"披露对象可能更广。","correct":false},{"id":"0","text":"需核查非调查用途限制","why":"不能默认培训用途获准。","correct":true}]},{"id":"S07-q4","stem":"某人调查前已经合法持有同一信息，课件条文载有相应限定。哪些做法合理？","options":[{"id":"3","text":"该限定等于免除所有其它保密义务","why":"其它依据仍需分析。","correct":false},{"id":"1","text":"区分原有信息与调查新获内容","why":"不能混同两者。","correct":true},{"id":"2","text":"听说过一点就能自由披露全部调查卷宗","why":"范围不能无限扩张。","correct":false},{"id":"0","text":"查明先前取得和持有的真实范围","why":"需要事实对应限定。","correct":true}]},{"id":"S07-q5","stem":"新闻报道员工被调查但尚无终局裁判。学习案例应如何表述？","options":[{"id":"2","text":"被调查等于已被终审定罪","why":"程序混淆。","correct":false},{"id":"1","text":"按题定事实练习要件，而非宣称真实人物有罪","why":"学习模拟不替代裁判。","correct":true},{"id":"3","text":"避免把旧统计作为当前定罪概率","why":"时点与样本限制仍在。","correct":true},{"id":"0","text":"区分指控、调查和已裁判事实","why":"程序状态必须准确。","correct":true}]}],"role":"半导体项目资料管理员","scenario":"团队既有普通工艺文件，也有题定依法公告的核心关键技术资料。调查中部分人员收到侦查保密令，还想把材料用于业务培训。","summary":"资料昂贵不等于依法指定核心技术；实体保护与调查中的保密命令也要分开处理。","variation":{"labels":["仅由公司盖“核心”章","存在题定法定公告依据"],"results":["不能直接证明符合特别制度指定条件。","再检查适用主体、行为、目的及地区等要件。"]},"worked":"先区分普通秘密与特别技术，再独立列出调查保密令。即使最终实体责任尚未确定，具体程序命令的义务也不能被随意忽略。"},{"id":"S08","title":"谁拿走、谁使用，都要查","case":"新能源图纸流转","pages":"82–86","scope":"课件旧第 9 条与 2025 修订反不正当竞争法第 10 条对照；本关行为按第 10 条","nodes":[{"label":"信息基础","text":"不为公众所知悉、具有商业价值并采取相应保密措施的技术、经营等商业信息。","fact":"不能只证明有人带走文件。"},{"label":"行为类型","text":"包括不正当获取、有关披露使用、违反保密义务，以及教唆引诱帮助等。","fact":"未亲自窃取仍可能涉及其它行为类型。"},{"label":"第三方与救济","text":"明知或应知有关不当行为仍获取、披露、使用等需分析；民事、行政和刑事条件不同。","fact":"条文编号更新不等于所有责任自动成立。"}],"evidence":[{"label":"资料记录","text":"图纸未公开，有商业价值；实行权限和保密约定。"},{"label":"接收证据","text":"竞争企业收到来源说明后仍把图纸用于新项目，具体范围可追踪。"}],"questions":[{"id":"S08-q1","stem":"依据本关 2025 修订法，企业主张图纸是商业秘密。哪些事实需要支持？","options":[{"id":"3","text":"所有曾在公司电脑出现的信息都自动受保护","why":"范围过大。","correct":false},{"id":"0","text":"不为公众所知悉","why":"对应信息基础条件。","correct":true},{"id":"2","text":"图纸文件名出现“内部”即可免除其它证明","why":"标签不足。","correct":false},{"id":"1","text":"商业价值及相应保密措施","why":"两者也须核查。","correct":true}]},{"id":"S08-q2","stem":"工程师违反保密义务把秘密文件交给他人。哪些分析相关？","options":[{"id":"2","text":"只要最初工作访问合法，之后披露都合法","why":"混淆最初接触与后续用途。","correct":false},{"id":"0","text":"违反保密义务后的披露","why":"属于所列行为类型方向。","correct":true},{"id":"1","text":"接收方后续使用及知情状态","why":"不同主体需分别分析。","correct":true},{"id":"3","text":"没有盗窃行为就排除所有侵犯秘密的路径","why":"行为类型不止盗窃。","correct":false}]},{"id":"S08-q3","stem":"竞争企业明知来源不当仍获取并使用秘密资料。哪些判断正确？","options":[{"id":"1","text":"不亲自盗取不能自动免除有关责任","why":"后续行为也有规定。","correct":true},{"id":"2","text":"付给员工报酬便转成合法授权","why":"报酬不改变来源。","correct":false},{"id":"0","text":"第三方知情获取使用需独立分析","why":"不能只盯最初携出者。","correct":true},{"id":"3","text":"只要称员工是顾问便不受任何规则影响","why":"身份标签不取代事实。","correct":false}]},{"id":"S08-q4","stem":"经理教唆他人员工违反保密义务提供秘密资料。哪些事实相关？","options":[{"id":"0","text":"教唆引诱帮助等行为","why":"现行第 10 条有相关列举。","correct":true},{"id":"1","text":"资料属性及实际获取披露使用","why":"需与要件对应。","correct":true},{"id":"2","text":"经理没有亲手下载就一定不涉及该条","why":"忽略帮助诱导路径。","correct":false},{"id":"3","text":"所有招聘同行员工都自动是教唆侵害","why":"正常招聘不能直接等同不当行为。","correct":false}]},{"id":"S08-q5","stem":"诉讼准备引用课件旧第 9 条并把举报当成定罪。哪些修正合理？","options":[{"id":"2","text":"保存合法证据并按具体救济路径核查","why":"事实支撑比先下结论更重要。","correct":true},{"id":"3","text":"一旦符合某项民事要件就自动满足全部刑事要件","why":"不同责任标准不能直接互换。","correct":false},{"id":"0","text":"标明 2025 修订后的相关条文位置","why":"避免使用过时编号冒充现行。","correct":true},{"id":"1","text":"区分举报、裁判和不同责任条件","why":"程序与要件要清楚。","correct":true}]}],"role":"新能源企业合规负责人","scenario":"工程师违背保密义务把未公开图纸带给竞争企业，对方明知来源仍安排研发使用。公司正保存访问记录和许可资料。","summary":"保护条件、获取方式、后续使用和第三方知情要分开证明；2025 年修订后相关商业秘密规定位于第 10 条。","variation":{"labels":["只有文件相似","有保密条件及知情使用证据"],"results":["还需证明秘密条件、来源与行为，不能直接完成责任判断。","可逐项建立分析，具体责任和救济仍按各自规则核查。"]},"worked":"先列信息的三个条件，再画工程师到竞争企业的流转。对每个主体分别写行为和知情证据；不要把民事要件、行政处理和刑事标准混成一句结论。"},{"id":"S09","title":"改革建议还不是生效法律","case":"印度合作合同的法律简报","pages":"69–70、31–32","scope":"课件对印度保密义务路径及 2024 年法律委员会报告的介绍；不把报告当现行立法","nodes":[{"label":"既有路径","text":"课件介绍合同法和保密义务等保护路径。","fact":"没有某种专门法不等于一切信息都可任意取用。"},{"label":"报告性质","text":"2024 报告建议制定专门法并附草案，包含公共利益等例外建议。","fact":"提案和生效法律不是同一状态。"},{"label":"证据与时期","text":"具体争议需看适用时点、义务、取得和使用事实。","fact":"不能把旧报告当所有时期现行制度的完整清单。"}],"evidence":[{"label":"合同文件","text":"包含具体保密用途与接收人安排，尚待核查执行与适用法。"},{"label":"法律附件","text":"2024 报告及其草案，被业务人员标成“已经生效的法律”。"}],"questions":[{"id":"S09-q1","stem":"合同附件是 2024 法律委员会报告及草案。哪些说法准确？","options":[{"id":"1","text":"需另查当时实际立法状态","why":"不能从标题推定。","correct":true},{"id":"2","text":"附有法案草稿便自动已生效","why":"草稿性质不同。","correct":false},{"id":"0","text":"报告建议与生效法律必须区分","why":"官方发布不等于立法完成。","correct":true},{"id":"3","text":"报告所有观点都能直接取代法院适用法","why":"缺少规范依据。","correct":false}]},{"id":"S09-q2","stem":"团队称不存在某种专门秘密法就没有任何保护。按课件介绍，哪些纠正有依据？","options":[{"id":"2","text":"没有专门法便可随意取走所有资料","why":"结论过度。","correct":false},{"id":"1","text":"保密义务等既有路径需核查","why":"专门立法不是唯一来源类型。","correct":true},{"id":"3","text":"只要签了合同便保证任何条款有效","why":"仍需适用法及范围审查。","correct":false},{"id":"0","text":"合同保密义务可能提供分析路径","why":"不能忽略合同。","correct":true}]},{"id":"S09-q3","stem":"报告建议设置公共利益和举报人等例外。应如何使用这一材料？","options":[{"id":"1","text":"核查具体行为是否有实际适用的规则依据","why":"不能只靠拟议例外。","correct":true},{"id":"0","text":"把它作为改革建议进行比较讨论","why":"保留来源性质。","correct":true},{"id":"2","text":"任何自称举报者都直接获得报告赋予的免责","why":"建议不自动产生权利。","correct":false},{"id":"3","text":"建议例外证明所有秘密都不值得保护","why":"政策目标不能如此扩大。","correct":false}]},{"id":"S09-q4","stem":"企业威胁以刑事程序处理普通客户名单争议。哪些分析适当？","options":[{"id":"1","text":"区分提出指控与最终证明","why":"程序状态很重要。","correct":true},{"id":"2","text":"报警意味着对方已经犯罪","why":"错误提升了程序结论。","correct":false},{"id":"3","text":"只要是劳动纠纷便不必核查任何实际行为","why":"同样不能一概排除。","correct":false},{"id":"0","text":"区分信息属性、保密义务与具体刑事构成","why":"不能用标签替代标准。","correct":true}]},{"id":"S09-q5","stem":"研究员制作跨国对照表。哪些栏目必要？","options":[{"id":"2","text":"哪些仍是建议或待核实信息","why":"透明标记证据边界。","correct":true},{"id":"1","text":"权利或义务基础及适用条件","why":"避免只比较制度名称。","correct":true},{"id":"3","text":"只按处罚看起来重不重给全部制度排名","why":"不足以比较具体保护路径。","correct":false},{"id":"0","text":"法域、资料日期和来源性质","why":"让不同制度可比较。","correct":true}]}],"role":"跨境合同研究员","scenario":"合作方把印度法律委员会 2024 年报告附到合同后，声称报告中的每项建议都已经成为可直接执行的条文。","summary":"先分清已存在的合同或保密义务路径、个案主张和改革建议，再判断哪个来源能支持眼前结论。","variation":{"labels":["材料是法律委员会报告","材料是经核实的有效规定或合同义务"],"results":["准确标为建议或草案，不能直接断言已经生效。","再判断适用范围和案件事实，仍不直接保证胜诉。"]},"worked":"给来源加上状态标签：既有规则、合同、主张、报告、草案。再把每条结论连到能支持它的来源，避免仅凭官方报告封面把提议升级成法律。"},{"id":"S10","title":"公开申请，还是继续保密","case":"制造企业的保护组合","pages":"6、11–15、21、25、37–38、88–91、96–97","scope":"专利与商业秘密的经营选择；反向工程须另查当地法与合同","nodes":[{"label":"专利交换","text":"申请专利通常需要公开技术，并以法定条件、地域和期限换取排他保护。","fact":"不是申请就保住秘密且自动全球有效。"},{"label":"持续保密","text":"秘密可在条件持续满足时维持保护，但他人独立研发等需与不当取得区分。","fact":"要投入权限、合作和人员流程管理。"},{"label":"经营组合","text":"外观、技术、参数、品牌和服务可分别配置资源。","fact":"公开内容与保密内容必须划清，不能把已公开部分仍当秘密。"}],"evidence":[{"label":"产品结构","text":"上市后容易观察和拆解的结构，可能很难长期维持秘密。"},{"label":"内部流程","text":"不随产品交付的制造参数，有访问限制；服务质量另依团队管理形成。"}],"questions":[{"id":"S10-q1","stem":"产品结构上市后容易被合法观察。哪些策略考虑合理？","options":[{"id":"0","text":"评估能否长期保持秘密","why":"信息可得性影响秘密条件。","correct":true},{"id":"1","text":"提前评估专利及公开时序","why":"避免公开后再盲目决策。","correct":true},{"id":"2","text":"加上保密标签就可阻止所有独立观察","why":"标签不能改变实际可得性。","correct":false},{"id":"3","text":"凡容易看到的东西都绝对不可能有任何保护","why":"还要看其它权利对象与条件。","correct":false}]},{"id":"S10-q2","stem":"制造参数不随产品交付，访问人数有限。哪些因素相关？","options":[{"id":"2","text":"只要决定保密便永远不会泄露","why":"经营选择不是结果保证。","correct":false},{"id":"1","text":"持续管理成本及人员流程","why":"保密需要落实。","correct":true},{"id":"3","text":"无需分析他人独立研发的可能","why":"独立来源影响保护策略。","correct":false},{"id":"0","text":"秘密状态和因保密产生的价值","why":"是保护基础。","correct":true}]},{"id":"S10-q3","stem":"同一技术已在公开专利文件中充分披露。哪些判断正确？","options":[{"id":"1","text":"未公开的另外参数需独立判断","why":"不能不加分析地一并否定或保护。","correct":true},{"id":"3","text":"公开一处信息便代表公司所有资料都公开","why":"应明确边界。","correct":false},{"id":"0","text":"已公开部分不能仅凭内部声明继续当秘密","why":"实际公开影响秘密性。","correct":true},{"id":"2","text":"申请专利当然使所有技术永久保密","why":"与公开交换特点不符。","correct":false}]},{"id":"S10-q4","stem":"企业想把专利和秘密组合使用。哪些方案有依据？","options":[{"id":"2","text":"用合同和访问控制管理真正保密部分","why":"让策略落到流程。","correct":true},{"id":"3","text":"用一份专利证代替所有信息管理","why":"工具功能不同。","correct":false},{"id":"1","text":"评估地域、期限和执行成本","why":"保护工具有不同约束。","correct":true},{"id":"0","text":"分别列明拟公开和保密的信息范围","why":"避免自相矛盾。","correct":true}]},{"id":"S10-q5","stem":"餐饮企业配方容易被学习，主要优势来自服务。哪些经营选择合理？","options":[{"id":"1","text":"对具体秘密的保护成本与价值作比较","why":"避免所有信息一律最高投入。","correct":true},{"id":"0","text":"评估服务、品牌和持续创新投入","why":"竞争不只来自保密。","correct":true},{"id":"2","text":"争议处理时考虑证据、成本和合作关系","why":"法律与商业决策需连接。","correct":true},{"id":"3","text":"因为重视服务便可忽略他人的全部知识产权","why":"自身策略不取消他人权利。","correct":false}]}],"role":"企业技术战略负责人","scenario":"产品外壳上市后易被观察，核心制造参数留在厂内难以获知。团队还拥有服务流程和客户关系，预算有限。","summary":"按信息特点组合保护：可公开技术、难观察参数和服务能力分别处理。没有一种权利能替代全部商业竞争力。","variation":{"labels":["信息上市后容易合法获知","信息保留内部且可合理控制"],"results":["长期保密的可行性下降，应先评估专利条件及公开时序。","可评估秘密保护成本和风险，同时规划合作与离职管理。"]},"worked":"先按可观察程度、可专利性、公开后果和管理成本列清单。结构、参数和服务可以用不同策略，是否提起争议还要权衡证据、成本及合作关系。"}],"finalQuestions":[{"id":"F01-q1","stem":"新品牌买下域名和一张原创新插画的纸质印刷许可。现准备把插画做成广告视频并在海外开店。哪些事项仍需核查？","options":[{"id":"0","text":"视频利用是否超出插画许可范围","why":"纸质印刷不直接覆盖新用途。","correct":true},{"id":"2","text":"既有付款统一覆盖所有权利与地区","why":"不同对象和用途需分开。","correct":false},{"id":"3","text":"外国作品在保护地的有关规则","why":"跨境利用仍需适用范围。","correct":true},{"id":"1","text":"目标市场商标权利与冲突","why":"域名不能代替商标核查。","correct":true}],"sourceUnit":"F01","scope":"依据有关课件条约框架；题定均为虚构项目，不推定所有国内法相同","pages":"Session 2：3、32–33；Session 3：15、18、26、40；Session 5：3"},{"id":"F01-q2","stem":"茶饮企业官网公布菜单，另把未公开配方设置权限并签保密约定；店名只做公司登记。哪些判断成立？","options":[{"id":"2","text":"公司登记证明同名商标在所有商品上无冲突","why":"登记类型和范围混同。","correct":false},{"id":"3","text":"店名作为来源标志使用仍需商标核查","why":"使用功能不同于主体登记。","correct":true},{"id":"1","text":"配方需逐项检验秘密、价值和措施","why":"题定事实提供分析线索。","correct":true},{"id":"0","text":"公开菜单不能仅凭内部标签变成秘密","why":"实际公开状态是关键。","correct":true}],"sourceUnit":"F01","scope":"依据有关课件条约框架；题定均为虚构项目，不推定所有国内法相同","pages":"Session 2：3、32–33；Session 3：15、18、26、40；Session 5：3"},{"id":"F01-q3","stem":"软件团队独立实现竞品功能，却复制其页面插画并使用近似品牌销售类似服务。哪些分析方向有依据？","options":[{"id":"3","text":"功能相同就必然复制了代码","why":"不能省略具体复制证据。","correct":false},{"id":"2","text":"代码独立便说明所有素材都无版权问题","why":"不能由一项事实覆盖全部对象。","correct":false},{"id":"1","text":"品牌使用需分析标志、服务与混淆","why":"不同权利可在同一产品叠加。","correct":true},{"id":"0","text":"独立实现功能与复制插画分开判断","why":"想法和具体表达不同。","correct":true}],"sourceUnit":"F01","scope":"依据有关课件条约框架；题定均为虚构项目，不推定所有国内法相同","pages":"Session 2：3、32–33；Session 3：15、18、26、40；Session 5：3"},{"id":"F01-q4","stem":"酒商将非产地葡萄酒标注受保护酒类地理标志加“风格”，无适用例外，并使用未经许可的新摄影作品。哪些判断正确？","options":[{"id":"2","text":"标明真实产地同时解决所有酒标与图片权利","why":"两个制度都不能这样简化。","correct":false},{"id":"3","text":"照片没有登记便可以任意商业利用","why":"忽略自动保护原则。","correct":false},{"id":"1","text":"照片是否获准使用需单独核查","why":"标签问题不替代版权问题。","correct":true},{"id":"0","text":"“风格”不当然排除酒类特别保护问题","why":"第 23 条并不只看一般混淆。","correct":true}],"sourceUnit":"F01","scope":"依据有关课件条约框架；题定均为虚构项目，不推定所有国内法相同","pages":"Session 2：3、32–33；Session 3：15、18、26、40；Session 5：3"},{"id":"F01-q5","stem":"总部给加盟商两年品牌许可，同时仅允许内部培训使用一段音乐录音。加盟商要卖掉商标并把录音用于公开广告。哪些判断成立？","options":[{"id":"3","text":"加盟费能一次买断全部品牌和音乐权利","why":"付款不等于题定全面授权。","correct":false},{"id":"2","text":"录音与歌曲作品的相关权利仍应区分","why":"权利可能叠加。","correct":true},{"id":"0","text":"品牌使用许可不直接赋予商标转让权","why":"需看实际权利归属。","correct":true},{"id":"1","text":"内部用途录音许可不能直接覆盖广告","why":"用途变化需核查。","correct":true}],"sourceUnit":"F01","scope":"依据有关课件条约框架；题定均为虚构项目，不推定所有国内法相同","pages":"Session 2：3、32–33；Session 3：15、18、26、40；Session 5：3"},{"id":"F02-q1","stem":"智能水杯有新外形、技术结构、程序代码和留在工厂的秘密参数。哪些保护拆分合理？","options":[{"id":"0","text":"外形与技术结构分别分析外观和技术方案","why":"对象不同。","correct":true},{"id":"3","text":"提交一份外观申请就必然覆盖全部对象","why":"一种工具不能包办全部保护。","correct":false},{"id":"1","text":"程序具体代码可进入版权分析","why":"TRIPS 有程序保护规定。","correct":true},{"id":"2","text":"内部参数按秘密条件与管理情况分析","why":"不是所有资料都自动秘密。","correct":true}],"sourceUnit":"F02","scope":"TRIPS、EPC 课件框架；题面涉及欧洲软件时明确限定 EPC","pages":"Session 2：33；Session 4：3–6、18–22、31–35；Session 5：88–91"},{"id":"F02-q2","stem":"公司提交 PCT 后公开完整技术文件，仍把同一公开内容称为永久商业秘密。哪些纠正正确？","options":[{"id":"3","text":"真正未公开的其它信息需另作秘密条件分析","why":"边界要具体划分。","correct":true},{"id":"1","text":"充分公开影响该内容的秘密性","why":"内部标签不能逆转公开。","correct":true},{"id":"0","text":"PCT 申请不等于所有国家已授权","why":"程序与结果应区分。","correct":true},{"id":"2","text":"PCT 能在不公开任何内容的前提下自动全球授权","why":"错误合并了两个期待。","correct":false}],"sourceUnit":"F02","scope":"TRIPS、EPC 课件框架；题面涉及欧洲软件时明确限定 EPC","pages":"Session 2：33；Session 4：3–6、18–22、31–35；Session 5：88–91"},{"id":"F02-q3","stem":"欧洲项目的软件控制机器制动，样机有效，尚未检索已有技术。哪些判断适当？","options":[{"id":"0","text":"技术过程控制可支持技术特征分析","why":"符合进一步技术效果方向。","correct":true},{"id":"3","text":"代码有版权就证明技术方案必定可专利","why":"版权与专利标准不同。","correct":false},{"id":"2","text":"软件能运行便意味着最终授权已确定","why":"条件不足。","correct":false},{"id":"1","text":"仍需新颖性与创造性审查","why":"样机有效和技术性不能替代。","correct":true}],"sourceUnit":"F02","scope":"TRIPS、EPC 课件框架；题面涉及欧洲软件时明确限定 EPC","pages":"Session 2：33；Session 4：3–6、18–22、31–35；Session 5：88–91"},{"id":"F02-q4","stem":"企业拥有改进产品专利，仍采用他人有效基础专利方法；产品也需监管批准。哪些事项应分开核查？","options":[{"id":"0","text":"基础方法实施许可","why":"有自己的专利不等于自由实施。","correct":true},{"id":"1","text":"产品监管审批","why":"专利不替代产品合规。","correct":true},{"id":"2","text":"改进专利的有效状态与范围","why":"权利资料本身仍需准确。","correct":true},{"id":"3","text":"改进专利一获准就消灭全部基础权利","why":"没有这种自动结果。","correct":false}],"sourceUnit":"F02","scope":"TRIPS、EPC 课件框架；题面涉及欧洲软件时明确限定 EPC","pages":"Session 2：33；Session 4：3–6、18–22、31–35；Session 5：88–91"},{"id":"F02-q5","stem":"采购方买芯片时不知且无合理理由知道非法布图，收到充分通知后还有旧库存；又要新下订单。哪些判断正确？","options":[{"id":"1","text":"新订单应与通知前库存分开分析","why":"特别范围不可随意扩大。","correct":true},{"id":"3","text":"保留采购、通知与订单时间证据","why":"时间与条文条件直接相关。","correct":true},{"id":"2","text":"新订单也因最初善意而永远免费销售","why":"忽略知情阶段变化。","correct":false},{"id":"0","text":"旧库存的特别处理可能伴随合理使用费","why":"不能把善意理解为永久免费。","correct":true}],"sourceUnit":"F02","scope":"TRIPS、EPC 课件框架；题面涉及欧洲软件时明确限定 EPC","pages":"Session 2：33；Session 4：3–6、18–22、31–35；Session 5：88–91"},{"id":"F03-q1","stem":"品牌在甲国注册商标并获得专利，乙国手续未做，准备进入乙国销售。哪些工作有依据？","options":[{"id":"1","text":"区分国际申请便利与当地授权结果","why":"不能把程序协调当结果统一。","correct":true},{"id":"0","text":"分别核查乙国商标与专利状态","why":"两类权利都有地域分析问题。","correct":true},{"id":"2","text":"甲国证书自动排除乙国一切在先权利","why":"无此跨境效果。","correct":false},{"id":"3","text":"核对当地产品准入要求","why":"知识产权证书不代替产品监管。","correct":true}],"sourceUnit":"F03","scope":"各题依课件给定制度作判断；历史条文比较不当作现行完整合规清单","pages":"Session 3：18–22、44–45；Session 4：6、11；Session 5：53–78"},{"id":"F03-q2","stem":"饮料品牌试图以不同商品为理由借用知名注册商标，并暗示合作。哪些证据相关？","options":[{"id":"1","text":"是否建立联系及可能损害权利人利益","why":"跨类保护需具体条件。","correct":true},{"id":"3","text":"合作宣传的实际内容与真实性","why":"商业联系证据不能省略。","correct":true},{"id":"2","text":"不同商品自动排除所有商标问题","why":"忽略驰名等路径。","correct":false},{"id":"0","text":"相关公众对知名商标的认知","why":"是驰名分析方向。","correct":true}],"sourceUnit":"F03","scope":"各题依课件给定制度作判断；历史条文比较不当作现行完整合规清单","pages":"Session 3：18–22、44–45；Session 4：6、11；Session 5：53–78"},{"id":"F03-q3","stem":"多国品牌管理表只记录续展，不记录加盟使用；公司把 TRIPS 七年写成每国精确期限。哪些修正合理？","options":[{"id":"3","text":"只要续展成功，不使用永远不会产生问题","why":"忽略维持条件。","correct":false},{"id":"1","text":"另建真实使用与受控制使用记录","why":"续展不替代使用维持。","correct":true},{"id":"2","text":"记录各保护地规则和期限","why":"便于正确管理。","correct":true},{"id":"0","text":"注明七年为条约最低注册及续展期限","why":"具体成员可能更长。","correct":true}],"sourceUnit":"F03","scope":"各题依课件给定制度作判断；历史条文比较不当作现行完整合规清单","pages":"Session 3：18–22、44–45；Session 4：6、11；Session 5：53–78"},{"id":"F03-q4","stem":"跨境合作接收带保密标记的图纸，来源不明；另一份资料按题定课件框架已依法指定为须审查出口的核心技术。哪些步骤适当？","options":[{"id":"0","text":"追查图纸来源、授权及知情线索","why":"接收使用也需分析。","correct":true},{"id":"2","text":"商业合同签字便免除所有保密和管制问题","why":"不同义务不能被一纸合同抹去。","correct":false},{"id":"1","text":"核查特别技术出口的程序","why":"公司许可不替代主管要求。","correct":true},{"id":"3","text":"明确具体法域及适用版本","why":"不能把历史课件条文直接当最新清单。","correct":true}],"sourceUnit":"F03","scope":"各题依课件给定制度作判断；历史条文比较不当作现行完整合规清单","pages":"Session 3：18–22、44–45；Session 4：6、11；Session 5：53–78"},{"id":"F03-q5","stem":"法律简报把印度 2024 报告、WIPO 联合建议和已生效法条放在一起。哪些整理方式正确？","options":[{"id":"1","text":"注明法域与时点","why":"比较规则不能脱离适用范围。","correct":true},{"id":"0","text":"标注法律、建议和草案等来源性质","why":"层次影响支持结论的力度。","correct":true},{"id":"3","text":"将教师评价与法条要求分列","why":"不把个人评价作为唯一答案。","correct":true},{"id":"2","text":"只要由官方发布就全部同等生效","why":"报告与立法不同。","correct":false}],"sourceUnit":"F03","scope":"各题依课件给定制度作判断；历史条文比较不当作现行完整合规清单","pages":"Session 3：18–22、44–45；Session 4：6、11；Session 5：53–78"},{"id":"F04-q1","stem":"题定紧急情形下获准豁免专利事先协商，企业便主张不付报酬、无限使用，并认为药品审批自动完成。哪些纠正正确？","options":[{"id":"2","text":"仍需核查范围、通知和报酬等规定","why":"不能把紧急写成全面免除。","correct":true},{"id":"3","text":"紧急状态可由企业一句话产生全部豁免","why":"需制度依据。","correct":false},{"id":"1","text":"药品审批与专利许可需要分别处理","why":"两个程序不同。","correct":true},{"id":"0","text":"事先协商豁免不自动取消其它许可条件","why":"例外范围有限。","correct":true}],"sourceUnit":"F04","scope":"TRIPS 一般框架及题定德国、台湾地区课件例子；不同制度不直接互换","pages":"Session 2：37–39；Session 4：23–30；Session 5：27–32、46–49、74、93–94"},{"id":"F04-q2","stem":"合格进口成员按第 31bis 条安排药品进口，另有未公开试验资料问题。哪些判断有依据？","options":[{"id":"3","text":"报酬安排需按机制避免规定情形下的重复计算","why":"存在特定制度衔接。","correct":true},{"id":"2","text":"取得专利强制许可就当然拥有他人的全部试验资料","why":"权利对象不同。","correct":false},{"id":"0","text":"药品出口机制仍须满足条文与附件条件","why":"不是任意出口许可。","correct":true},{"id":"1","text":"专利许可与监管数据制度需分别分析","why":"不能互相替代。","correct":true}],"sourceUnit":"F04","scope":"TRIPS 一般框架及题定德国、台湾地区课件例子；不同制度不直接互换","pages":"Session 2：37–39；Session 4：23–30；Session 5：27–32、46–49、74、93–94"},{"id":"F04-q3","stem":"适用题定德国 HGB 框架的员工签了离职四年禁业条款，没有补偿，同时负有真实秘密的保密义务。哪些分析正确？","options":[{"id":"1","text":"需核查补偿要求及合理范围","why":"签字不替代法定条件。","correct":true},{"id":"3","text":"竞业条款有问题就能随意带走秘密图纸","why":"推论过度。","correct":false},{"id":"0","text":"四年期限与所述最多两年要求冲突","why":"按题定框架判断。","correct":true},{"id":"2","text":"竞业条款问题与特定秘密义务分开分析","why":"不是一项出问题另一项必然消失。","correct":true}],"sourceUnit":"F04","scope":"TRIPS 一般框架及题定德国、台湾地区课件例子；不同制度不直接互换","pages":"Session 2：37–39；Session 4：23–30；Session 5：27–32、46–49、74、93–94"},{"id":"F04-q4","stem":"受题定调查保密令约束者想把调查材料发进培训群；培训方又整本扫描教材替代购买。哪些方向相关？","options":[{"id":"0","text":"调查内容的用途与披露对象限制","why":"培训标签不能替代命令范围。","correct":true},{"id":"1","text":"教材利用的具体例外与正常市场影响","why":"教育目的不是万能许可。","correct":true},{"id":"2","text":"两种行为都叫学习，所以当然免责","why":"制度条件不同。","correct":false},{"id":"3","text":"分别说明所依赖规则和实际事实","why":"避免把两个问题混作一个结论。","correct":true}],"sourceUnit":"F04","scope":"TRIPS 一般框架及题定德国、台湾地区课件例子；不同制度不直接互换","pages":"Session 2：37–39；Session 4：23–30；Session 5：27–32、46–49、74、93–94"},{"id":"F04-q5","stem":"企业面临离职文件争议，已举报并正在调查，内部报告却称“法院已认定全部人员犯罪”。哪些改进正确？","options":[{"id":"2","text":"在商业决策中考虑证据、成本和合作关系","why":"不只看最重处罚数字。","correct":true},{"id":"1","text":"分别列保护条件、行为与知情证据","why":"事实应对应要件。","correct":true},{"id":"3","text":"用媒体标题替代法律依据和调查事实","why":"不能支撑可靠判断。","correct":false},{"id":"0","text":"准确区分举报、调查和裁判状态","why":"不得提升程序结论。","correct":true}],"sourceUnit":"F04","scope":"TRIPS 一般框架及题定德国、台湾地区课件例子；不同制度不直接互换","pages":"Session 2：37–39；Session 4：23–30；Session 5：27–32、46–49、74、93–94"}],"finalGroups":[{"id":"F01","title":"品牌上市项目","scope":"依据有关课件条约框架；题定均为虚构项目，不推定所有国内法相同","pages":"Session 2：3、32–33；Session 3：15、18、26、40；Session 5：3"},{"id":"F02","title":"产品研发项目","scope":"TRIPS、EPC 课件框架；题面涉及欧洲软件时明确限定 EPC","pages":"Session 2：33；Session 4：3–6、18–22、31–35；Session 5：88–91"},{"id":"F03","title":"跨境经营项目","scope":"各题依课件给定制度作判断；历史条文比较不当作现行完整合规清单","pages":"Session 3：18–22、44–45；Session 4：6、11；Session 5：53–78"},{"id":"F04","title":"公共利益与人员流动","scope":"TRIPS 一般框架及题定德国、台湾地区课件例子；不同制度不直接互换","pages":"Session 2：37–39；Session 4：23–30；Session 5：27–32、46–49、74、93–94"}]};
